INSERT INTO Comments VALUES(26,'','2','1960/05/02','["2"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">02.05.1960</span><span style=" font-weight:600;"><br />Stilllegung Turmstraße (zwischen Rathenower Straße und Stromstraße), Pankstraße, Prinzenallee, Wollankstraße, Pankower Allee, Provinzstraße, Drontheimer Straße, Koloniestraße<br /></span></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" width="834" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td width="70" style=" vertical-align:top;">\u000a<p align="center" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">2<br />BVG-West</p></td>\u000a<td style=" vertical-align:top;">\u000a<p align="justify" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">Bernauer Straße/Wolliner Straße - Bernauer Straße - Strelitzer Straße - Wattstraße - Voltastraße - Hussitenstraße - Grenzstraße - Schulzendorfer Straße - Sellerstraße - Am Nordhafen - Fennbrücke - Perleberger Straße - Rathenower Straße - <span style=" color:#ff0000;">Alt-Moabit </span>- Gotzkowskystraße - Franklinstraße - Marschstraße - Knie - Hardenbergstraße - Bf. Zoo - Breitscheidplatz - Tauentzeienstraße - Wittenbergplatz - Kleiststraße - Nollendorfplatz - Bülowstraße - Yorckstraße - Gneisenaustraße - Südstern - Hasenheide - Hermannplatz - Sonnenallee - Reuterstraße - Pflügerstraße - Friedelstraße - Ohlauer Stra