INSERT INTO Comments VALUES(29,unistr('02.06.1991\u000aLinienänderungen wegen Wegfall von E-Linien\u000aNeue Liniennummern im Nachtverkehr \u000a'),'23','1960/06/01','["23"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">02.06.1991</span><br />Linienänderungen wegen Wegfall von E-Linien<br />Neue Liniennummern im Nachtverkehr </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Da im Busnetz ein neues einheitliches Liniennummernsystem bei BVB und BVG eingeführt wurde, mussten auch einige Verstärkerlinien, die mit einem zusätzlichen &quot;E&quot; gekennzeichnet waren, neue Liniennummern erhalten. Die Linie 16E wurde zur Linie 36, die Linie 25E zur Linie 23. Auch die Linie 88 musste in Linie 81 umbenannt werden, da die Liniennummer 88 ab 02.06.1991 der Schöneicher-Rüdersdorfer Straßenbahn zugeteilt wurde. Im Nachtverkehr wurde ein einheitliches Nachtnetz eingeführt, deren Liniennummer ein &quot;N&quot; vorangestellt wurde.</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" color:#ff0000;">entfällt</span></p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(31,'','23','1960/05/02','["23"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">02.05.1960</span><span style=" font-weight:600;"><br />Stilllegung Turmstraße (zwischen Rathenower Straße und Stromstraße), Pankstraße, Prinzenallee, Wollankstraße, Pankower Allee, Provinzstraße, Drontheimer Straße, Koloniestraße</span></p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; font-weight:600;"></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Da die Hauptwerkstatt der BVG in der Uferstaße weiterhin anfahrbar sein mußte, blieben einige Straßenzüge als Betriebsstrecke ohne Fahrgastverkehr weiterhin erhalten.</span></p></body></html>'),0,0,'2012-07-01 13:56:48');
