INSERT INTO Comments VALUES(119,unistr('30.06.1961\u000a2.Gleis Pasewalker Straße \u000a'),'49','1961/06/30','["49"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">30.06.1961</span><br />2.Gleis Pasewalker Straße </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">In der Pasewalker Straße wurde zum 30.06.1961 das zweite Gleis in Betrieb genommen. Dieser Abschnitt wurde von der Linie 49 (BVG-Ost) planmäßig befahren</span></p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(120,'','3','1961/07/01','["3"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">01.07.1961</span><br />Stilllegung Schöneberger Straße - Alt-Tempelhof - Germaniastraße - Tempelhofer Weg - Erkstraße<br />Linienverkürzung der Linien 53 und 54 (BVG-West) </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Aufgrund von Baufreimachung für die U-Bahnlinie CII (spätere U6) in Tempelhof musste dieser Straßenbahnabschnitt stillgelegt werden.</span></p>\u000a<p align="justify" style="-qt-paragraph-type:empty; margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; font-style:italic;"></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td style=" vertical-align:top;">\u000a<p align="justify" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" color:#ff0000;">Neukölln, Elsenstraße/Heidelberger Straße</span> - Elsenstraße - Harzer Straße - Wildenbruchstraße - Sonnenallee - Hermannplatz - Hasenheide - Südstern - Gneisenaustraße - Yorckstraße - Goebenstraße - Pallasstraße - Goltzstraße - Grunewaldstraße - Berliner Straße - Brandenburgische Straße - Fehrbelliner Platz - Wilmersdorfer Straße - Berliner Straße - Luisenplatz - Schloßbrücke - Tauroggener Straße - Osnabrücker Straße - Kaiserin-Augusta-Allee - Alt-Moabit - Gotzkowskystraße - Turmstraße - Beusselstraße - Heckerbrücke - Ludwig-Hoffmann-Brücke - Seestraße - Osloer Straße - Osloer Straße/Grüntaler Straße</p></td>\u000a<td></td></tr>\u000a<tr>\u000a<td style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Die Linie 3 war bereits vor der Verlängerung zum 01.07.1961, mit einer Linienlänge von 22,2 km (Fahrzeit 80 Minuten), die längste Linie in Berlin-West. Ab 01.07.61 wurde diese Linie nochmals um 2,2 km verlängert. Die Gesamtfahrzeit betrug 87 Minuten je Richtung.</span></p></td>\u000a<td style=" vertical-align:top;"></td></tr></table></body></html>'),0,0,'2012-07-01 13:56:48');
