INSERT INTO Comments VALUES(130,unistr('01.10.1961\u000aStilllegung Tempelhofer Damm, Mariendorfer Damm, Lichtenrader Damm '),'98','1961/10/01','["98"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">01.10.1961</span><br />Stilllegung Tempelhofer Damm, Mariendorfer Damm, Lichtenrader Damm </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Diese Maßnahme sollte eigentlich wegen dem Berliner Mauerbau auf unbestimmte Zeit verschoben werden, da es auf dem Bussektor erhebliche Wagenprobleme gab (S-Bahnboykott). Der Betriebshof Tem (Tempelhof, Kaiserin-Augusta-Allee) wurde ebenfalls für die Straßenbahn am 01.10.1961 geschlossen. </span></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" width="834" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td width="70" style=" vertical-align:top;"></td></tr></table>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" color:#ff0000;">entfällt</span></p>\u000a<p align="justify" style="-qt-paragraph-type:empty; margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; font-style:italic;"><br /></p></body></html>'),0,0,'2012-07-01 13:56:48');
