INSERT INTO Comments VALUES(140,'','1120','1962/01/28','["84E"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt;">28.01.1962</span><br />Stilllegung Adlergestell<br />Inbetriebnahme Gleistrasse Adlershof westl. der Bahn</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">Altglienicke, Am Falkenberg - Am Falkenberg - Grünauer Straße - Köpenicker Straße - <span style=" color:#ff0000;">Gelände westl. der Bahn</span> - S-Bf. Adlershof - Rudower Chaussee - Dörpfeldtstraße - Konstadter Weg - Oberspreestraße - Lange Brücke - ?Grünstraße - ?Kirchstraße - ?Alt-Köpenick - Dammbrücke - Lindenstraße - Bahnhofstraße - Seelenbinderstraße - Bellevuestraße - Fürstenwalder Damm - ?Müggelseedamm - ?Bölschestraße - S-Bf. Friedrichshagen<br /><span style=" font-style:italic;">verkehrt nur im Berufsverkehr</span></p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(141,'','57','1952/10/13','["57"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">13.10.1952</span><br />Sperrung Oberbaumbrücke<br />Verlegung Endstelle Emser Platz in die Güntzelstraße/Pfalzburger Straße</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" color:#ff0000;">Wilmersdorf, Emser Platz</span> - Güntzelstraße - Fehrbelliner Platz - Hohenzollerndamm - Roseneck</p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(142,'','3','1953/01/15','["3"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">15.01.1953 / 16.01.1953</span><br />Straßenbahnspaltung zwischen Ostberlin und Westberlin<br />Stilllegung Prinzenallee, teilw. Gitschiner Straße - nördl. Wollankstraße, Hauptstraße (Wilhelmsruh) </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Am Nachmittag, des 15.01.1953 erfolgte die so genannte &quot;Straßenbahn-Spaltung&quot; in Berlin. Die BVG-Ost schickte wieder vermehrt, in den Vormittagsstunden, Straßenbahnfahrerinnen auf den Linien 74 und 95 in Richtung Westberlin, obwohl der Einsatz von Fahrerinnen auf Westberliner Gebiet nach damaligen Vorschriften nicht statthaft war. Die Züge wurden wieder nach Ostberlin zurück geschickt und die Züge der BVG-West wurden nicht nach Ostberlin geschickt, als Ersatz für das Fehlen der Züge der BVG-Ost.</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" color:#ff0000;">Bornholmer Straße/Björnsonstraße</span> - Bornholmer Straße - Wisbyer Straße - Gustav-Adolf-Straße - Langhansstraße - Antonplatz - Berliner Allee - Lichtenberger Straße - Weißenseer Weg - Roederplatz - Möllendorffstraße - Bf. Frankfurter Allee - Gürtelstraße - Scharnweberstraße - Weichselstraße - Holteistraße - Wühlischstraße - Kopernikusstraße - Warschauer Straße - Warschauer Straße/Mühlenstraße</p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(145,'','60','1962/05/02','["60"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">02.05.1962</span><br />Stilllegung Alboinstraße, Dominicusstraße (teilw.), Eythstraße, Giesensdorfer Straße, Jungfernstieg, Kaiser-Friedrich-Straße, Sachsendamm, Schloßstraße, Stuttgarter Platz, Suarezstraße, Wilhelmstraße </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Der Streckenabschnitt Giesensdorfer Straße, Wilhlmstraße und Jungfernstieg wurde wegen Brücken- und Straßenbauarbeiten stillgelegt.</span> </p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" width="834" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td width="70" style=" vertical-align:top;">\u000a<p align="center" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">60<br />BVG-West<br /></p></td>\u000a<td style=" vertical-align:top;">\u000a<p align="justify" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" color:#ff0000;">entfällt</span></p></td></tr>\u000a<tr>\u000a<td style=" vertical-align:top;"></td>\u000a<td style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"> </p></td></tr>\u000a<tr>\u000a<td style=" vertical-align:top;">\u000a<p align="center" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">73<br />BVG-West<br /></p></td>\u000a<td style=" vertical-align:top;">\u000a<p align="justify" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" color:#ff0000;">entfällt</span></p></td></tr></table>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Die Einstellung der Linie 60 war bereits zum 01.10.61 geplant, wurde aber wegen der angespannten Lage im Buswagenpark verschoben.<br />Der Betriebshof (Char) Charlottenburg, Königin-Elisabeth-Straße wurde weiterhin betrieben und in Berlin-West wuchs nun das Betriebsstreckennetz auf 2,5 km an. Der Betriebshof Steg (Steglitz, Hindenburgdamm) wurde ebenfalls für die Straßenbahn am 02.05.1962 geschlossen.</span><br /></p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(146,'','75','1962/06/20','["75"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">20.06.1962</span><br />Straßenumbau am Rathaus Spandau</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">Hakenfelde - Niederneundorfer Allee - Streitstraße - Neuendorfer Straße - Falkenseer Platz - Am Juliusturm - ?Breite Straße - ?Spandau, Markt - Carl-Schurz-Straße - <span style=" color:#ff0000;">?Münsingerplatz - ?Rathaus Spandau</span> - Klosterstraße - Pichelsdorfer Straße - Heerstraße - An der Heerstraße - Kaiserdamm - Reichskanzlerplatz - Masurenallee - S-Bf. Witzleben - Neue Kantstraße - Amtsgerichtsplatz - Kantstraße - Bf. Zoo, Kantstraße/Joachimstaler Straße</p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(147,'','76','1962/06/20','["76"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">20.06.1962</span><br />Straßenumbau am Rathaus Spandau</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">Johannesstift - Schönwalder Allee - Schönwalder Straße - Neuendorfer Straße - Falkenseer Platz - Am Juliusturm - ?Breite Straße - ?Spandau, Markt - Carl-Schurz-Straße -<span style=" color:#ff0000;"> ?Münsingerplatz - ?Rathaus Spandau </span>- Klosterstraße - Pichelsdorfer Straße - Heerstraße - Reichskanzlerplatz - Masurenallee - S-Bf. Witzleben - Neue Kantstraße - Kantstraße - Bf. Zoo, Kantstraße/Joachimstaler Straße</p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(148,'','75','1962/07/04','["75"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">04.07.1962</span><br />Straßenumbau am Rathaus Spandau </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Die seit 20.06.1952 bestehende Umleitung über Münsingerplatz in Richtung Bf. Zoo, wurde ab 04.07.1962 in beiden Richtungen befahren.</span> </p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" width="834" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td width="70" style=" vertical-align:top;"></td></tr></table>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">Hakenfelde - Niederneundorfer Allee - Streitstraße - Neuendorfer Straße - Falkenseer Platz - Am Juliusturm - ?Breite Straße - ?Spandau, Markt - Carl-Schurz-Straße - <span style=" color:#ff0000;">Münsingerplatz</span> - Klosterstraße - Pichelsdorfer Straße - Heerstraße - An der Heerstraße - Kaiserdamm - Reichskanzlerplatz - Masurenallee - S-Bf. Witzleben - Neue Kantstraße - Amtsgerichtsplatz - Kantstraße - Bf. Zoo, Kantstraße/Joachimstaler Straße</p></body></html>'),0,0,'2012-07-01 13:56:48');
