INSERT INTO Comments VALUES(152,'','44','1962/09/12','["44"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">12.09.1962</span><br />Linienänderung Linie 44 (BVG-West) </p>\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Diese Maßnahme wurde auf Ersuchen der britischen Schutzmacht durchgeführt, da ein reibungsloser Verkehr der Wachablösung für das sowjetische Ehrenmal im Tiergarten gewährleistet werden musste.</span></p>\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" color:#ff0000;">Moabit, Werftstraße - Werftstraße</span> - Alt-Moabit - Gotzkowskystraße - Franklinstraße - Marchstraße - Knie - Berliner Straße - Richard-Wagner-Platz - Wilmersdorfer Straße - Brandenburgische Straße - Fehrbelliner Platz - Blissestraße - Hildegardstraße - Kaiserallee - Schloßstraße - Hindenburgdamm - Händelplatz - Gelieustraße - Schützenstraße - Birkbuschstraße - Steglitz, Birkbuschstraße/Siemensstraße<br /></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" width="834" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td width="70" style=" vertical-align:top;"></td></tr></table></body></html>'),0,0,'2012-07-01 13:56:48');
