INSERT INTO Comments VALUES(176,'','74','1963/08/11','["74"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">11.08.1963</span><br />Linienänderungen Linien 74 und 74E (BVG-Ost) </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Sonntags wurde die Linie 74 aufgeteilt. Der erste Teil fuhr zwischen Pasedagplatz und Jüdenstraße, der zweite Teil fuhr als Pendelwagen zwischen Molkenmarkt und Leipziger Platz im 30-Minuten-Takt. Wektags fuhr die Linie 74 ohne Einschränkungen zwischen Pasedagplatz und Leipziger Platz.</span><br /></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">Weißensee, Pasedagplatz - Rennbahnstraße - Klement-Gottwald-Allee - Greifswalder Straße - Königstor - Neue Königstraße - ?Jostystraße - ?Prenzlauer Straße - Memhardstraße - Alexanderplatz - Alexanderstraße - Schicklerstraße - Stralauer Straße - Molkenmarkt - Mühlendamm - Gertraudenstraße - Spittelmarkt - Leipziger Straße - Leipziger Platz<br /><span style=" font-style:italic; color:#ff0000;">verkehrt nur werktags</span></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" width="834" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td width="70" style=" vertical-align:top;"></td></tr></table></body></html>'),0,0,'2012-07-01 13:56:48');
