INSERT INTO Comments VALUES(182,'','26','1963/09/29','["26"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">29.09.1963</span><br />Stilllegung nördl. Karl-Marx-Straße, Buschkrugallee</p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(183,'','1102','1963/09/29','["47.2"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">29.09.1963</span><br />Stilllegung nördl. Karl-Marx-Straße, Buschkrugallee</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">Rudow, Bahnhofstraße - Waltersdorfer Chaussee - Rudow, Stadtgrenze</p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(184,'','3','1963/11/15','["3"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">15.11.1963</span><br />Stilllegung Elsenstraße, Harzer Straße, Wildenbruchstraße, Hasenheide, Gneisenaustraße, Yorckstraße, Goebenstraße, Pallasstraße, Goltzstraße, Grunewaldstraße, Berliner Straße, Brandenburgische Straße </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Aufgrund von U-Bahnbauarbeiten der U-Bahnlinie H (spätere U7) in der Yorckstraße musste dieser Streckenabschnitt stillgelegt werden.</span><br /></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Durch diese Stilllegung war das Westberliner Straßenbahnnetz nun in zwei Teile geteilt.</span> <span style=" font-style:italic;">Im I.Teil wurden die Linien 2, 3, 53, 54, 55, 75 und 76 mit den Betriebshöfen Charlottenburg - Moabit - Schöneberg - sowie der Hauptwerkstatt Uferstraße bedient.</span> <span style=" font-style:italic;">Im II.Teil wurden die Linien 15, 27, 27E, 47, 95 und 96 mit dem Betriebshof Britz bedient.</span> <span style=" font-style:italic;">Beide Netze waren durch lange Betriebsstrecken miteinander verbunden. Ab Dezember 1963 wurde wegen dem U-Bahnbau in der Yorckstraße ca. 200 m Gleis entfernt, sodass ab diesen Zeitpunkt beide Teilnetze vorrübergehend nicht miteinander verbunden waren.</span> </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" color:#ff0000;">Fehrbelliner Platz</span> - Wilmersdorfer Straße - Berliner Straße - Luisenplatz - Schloßbrücke - Tauroggener Straße - Osnabrücker Straße - Kaiserin-Augusta-Allee - Alt-Moabit - Gotzkowskystraße - Turmstraße - Beusselstraße - Heckerbrücke - Ludwig-Hoffmann-Brücke - Seestraße - Osloer Straße - Osloer Straße/Grüntaler Straße</p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Da die Endstelle Fehrbelliner Platz nur eine Stumpfendstelle war, konnten ab 15.11.1963 auf der Linie 3 nur noch Verbundzüge vom Typ TM33 und TM36 fahren.</span></p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(185,'','1122','1963/12/15','["46.1"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">20.12.1963</span><br />Linienänderungen wegen dem Passierscheinabkommen</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">Niederschönhausen, Schillerstraße - Schillerstraße - Dietzgenstraße - Ossietzkyplatz - Kurt-Fischer-Straße - Kurt-Fischer-Platz - Grabbeallee - Schönholzer Straße - Breite Straße - Berliner Straße - Schönhauser Allee - Kastanienallee - Zionskirchplatz - Veteranenstraße - Invalidenstraße - Chausseestraße - Oranienburger Tor - Friedrichstraße - Am Weidendamm - Planckstraße - ?Clara-Zetkin-Straße - ?Georgenstraße - Am Kupfergraben - Am Kupfergraben</p></body></html>'),0,0,'2012-07-01 13:56:48');
