INSERT INTO Comments VALUES(200,'','96','1964/09/07','["96"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">07.09.1964</span><br />Freigabe Goerzallee Mehringdamm/Yorckstraße - Platz der Luftbrücke - Manfred-von-Richthofen-Straße - Werner-Voß-Damm - Boelckestraße - Manteuffelstraße - Attilaplatz - Atillastraße - Kaiser-Wilhelm-Straße - Lankwitzer Straße - S-Bf. Lichterfelde Ost - Kranoldplatz - Bismarckstraße - Ostpreußendamm - <span style=" color:#ff0000;">Wismarer Straße - Goerzallee - Lichterfelde, Goerzallee/Darser Straße</span></p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(201,'','27','1964/10/01','["27"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">01.10.1964</span><br />Stilllegung Spreewaldplatz, Ohlauer Straße, Friedelstraße, Pflügerstraße, Reuterstraße, Hermannplatz, Hermannstraße, Britzer Damm, Buckower Damm, Tauentzienstraße, Kleiststraße</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Durch diese Stillegung zerfiel das Straßenbahnnetz in drei Teilabschnitte. Im I.Teil wurden die Linien 53, 54, 55, 75 und 76 mit dem Betriebshof Charlottenburg, sowie der Hauptwerkstatt Uferstraße bedient. Im II.Teil wurden die Linien 15, 95 und 96 bedient. Im III.Teil wurde die Linie 47 bedient. Die Teilnetze II und III waren durch eine Betriebsstrecke zwischen Gradestraße und Hermannplatz miteinander verbunden und wurden vom Betriebshof Britz bedient.</span> </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Der Betriebshof Schön (Schöneberg, Belziger Straße) wurde ebenfalls für die Straßenbahn am 01.10.1964 geschlossen. Dieser Betriebshof beherbergte bis kurz vor seiner Schließung teilweise die Linie 55 und bis Juni 1964 die Linie 2.</span></p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(202,'','55','1964/10/01','["55"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">01.10.1964</span><br />Stilllegung Spreewaldplatz, Ohlauer Straße, Friedelstraße, Pflügerstraße, Reuterstraße, Hermannplatz, Hermannstraße, Britzer Damm, Buckower Damm, Tauentzienstraße, Kleiststraße</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">Hakenfelde - Niederneuendorfer Allee - Streitstraße - Neuendorfer Straße - Falkenseer Platz - Am Juliusturm - Gartenfelder Straße - Paulsternstraße - Nonnedammallee - S-Bf. Wernerwerk - Siemensdamm - Siemensplatz - Mörschbrücke - Tegeler Weg - S-Bf. Jungfernheide - Osnabrücker Weg - Tauroggener Straße - Schloßbrücke - Luisenplatz - Otto-Suhr-Allee - Ernst-Reuter-Platz - Hardenbergstraße - <span style=" color:#ff0000;">Bf. Zoo (Hardenbergstraße) </span></p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; color:#ff0000;"></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Durch diese Stillegung zerfiel das Straßenbahnnetz in drei Teilabschnitte. Im I.Teil wurden die Linien 53, 54, 55, 75 und 76 mit dem Betriebshof Charlottenburg, sowie der Hauptwerkstatt Uferstraße bedient. Im II.Teil wurden die Linien 15, 95 und 96 bedient. Im III.Teil wurde die Linie 47 bedient. Die Teilnetze II und III waren durch eine Betriebsstrecke zwischen Gradestraße und Hermannplatz miteinander verbunden und wurden vom Betriebshof Britz bedient.</span> </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Der Betriebshof Schön (Schöneberg, Belziger Straße) wurde ebenfalls für die Straßenbahn am 01.10.1964 geschlossen. Dieser Betriebshof beherbergte bis kurz vor seiner Schließung teilweise die Linie 55 und bis Juni 1964 die Linie 2.</span></p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; color:#ff0000;"></p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(203,'','83','1964/11/14','["83"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">14.11.1964</span><br />Inbetriebnahme Gleisschleife S-Bf. Mahlsdorf</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" color:#ff0000;">S-Bf. Mahlsdorf - Treskowstraße - Hönower Straße </span>- Hultschiner Damm - Mahlsdorfer Straße - S-Bf. Köpenick - Bahnhofstraße - Lindenstraße - Dammbrücke - ?Alt-Köpenick - ?Grünstraße - ?Kirchstraße - Kietzer Straße - Müggelheimer Straße - Wendenschloßstraße - Wendenschloß </p></body></html>'),0,0,'2012-07-01 13:56:48');
