INSERT INTO Comments VALUES(227,'','75','1966/01/24','["75"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">24.01.1966</span><br />Stilllegung Klosterstraße, Pichelsdorfer Straße, Heerstraße, Masurenallee, Neue Kantstraße, Kantstraße </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Diese Streckenstilllegung war bereits zum 01.10.1965 geplant, wurde dann aber auf den ersten Ersatztermin zum 01.12.1965 und ein weiteres mal auf den nächsten Ersatztermin zum 02.01.1966 verschoben. Auch der zweite Ersatztermin wurde dann auf den endgültigen Termin zum 24.01.1966 verschoben, da es Bauverzögerungen bei der neuen Buswendeanlage am U-Bf Ruhleben gab und das Busnetz in Spandau neu geordnet werden sollte.</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Die bisher auf der Linie 75E verkehrenden Exoten TED52/BED52 und TEG 29/52 verkehrten nun auf der Linie 54 zwischen Johannesstift und Richard-Wagner-Platz.<br /></span></p>\u000a<p align="justify" style="-qt-paragraph-type:empty; margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; font-style:italic;"><br /></p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(228,'','76','1966/01/24','["76"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">24.01.1966</span><br />Stilllegung Klosterstraße, Pichelsdorfer Straße, Heerstraße, Masurenallee, Neue Kantstraße, Kantstraße </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Diese Streckenstilllegung war bereits zum 01.10.1965 geplant, wurde dann aber auf den ersten Ersatztermin zum 01.12.1965 und ein weiteres mal auf den nächsten Ersatztermin zum 02.01.1966 verschoben. Auch der zweite Ersatztermin wurde dann auf den endgültigen Termin zum 24.01.1966 verschoben, da es Bauverzögerungen bei der neuen Buswendeanlage am U-Bf Ruhleben gab und das Busnetz in Spandau neu geordnet werden sollte.</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Die bisher auf der Linie 75E verkehrenden Exoten TED52/BED52 und TEG 29/52 verkehrten nun auf der Linie 54 zwischen Johannesstift und Richard-Wagner-Platz.<br /></span></p>\u000a<p align="justify" style="-qt-paragraph-type:empty; margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; font-style:italic;"><br /></p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(229,'','64','1966/03/11','["64"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">11.03.1966</span><br />Inbetriebnahme neue Gleisschleife Döhoffplatz</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">Hohenschönhausen, Falkenberger Straße - Falkenberger Straße - Wartenberger Straße - Hauptstraße - Berliner Straße - Hohenschönhauser Straße - Oderbruchstraße - Leninallee - ?Alexanderplatz - ?Kleine Frankfurter Straße - ?Jacobystraße - Alexanderstraße - Jannowitzbrücke - Brückenstraße - Köpenicker Straße - Inselstraße - Wallstraße - Spittelmarkt - <span style=" color:#ff0000;">?Leipziger Straße - ?Jerusalemer Straße</span> - Krausenstraße - Dönhoffplatz</p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(230,'','96','1966/05/02','["96"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">02.05.1966</span><br />Stilllegung Mehringdamm, Manfred-von-Richthofen-Straße, Werner-Voß-Damm, Attilastraße, Kaiser-Wilhelm-Straße, Lankwitzer Straße, Ostpreußendamm, Wismarer Straße, Goerzallee<br />Einsatzende der Wagen vom Typ T24, B24 und B25 bei der BVG-West<br /></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Auf Grund einer aufsichtsbehördlichen Anordnung durften ab 02.05.1966 keine Wagen mehr mit offenen Plattformen (T24 / B24 / B25) im Fahrgastverkehr eingesetzt werden.</span></p></body></html>'),0,0,'2012-07-01 13:56:48');
