INSERT INTO Comments VALUES(232,'','15','1966/07/01','["15"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">01.07.1966</span><br />Stilllegung Sonnenallee, Braunschweiger Straße, Karl-Marx-Straße, Silbersteinstraße, Hertastraße, Mariendorfer Weg, Gottlieb-Dunkel-Straße, Rixdorfer Straße, Alt-Mariendorf, Großbeerenstraße, Daimlerstraße<br />Ende Beiwagenbetrieb bei der BVG-West</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Ab 01.07.1966 entfiel bei der BVG-West die Bezeichnung &quot;A&quot; vor der Busliniennummer und im Westberliner Straßenbahnnetz wurden keine Straßenbahnbeiwagen im Fahrgastverkehr mehr eingesetzt, mit Ausnahme der beiden Beiwagen vom Typ BED52 auf der Linie 54</span>.</p></body></html>'),0,0,'2012-07-01 13:56:48');
