INSERT INTO Comments VALUES(240,'','1101','1963/09/29','["47.1"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">01.10.1966</span><br />Stilllegung (BVG-West) Gradestraße, Blaschkoallee, Buschkrugallee, Rudower Straße, Neuköllner Straße</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Damit war das Straßenbahnbahnnetz in Westberlin nur noch zwischen den Bezirken Charlottenburg und Spandau auf den Linien 53, 54 und 55 befahrbar. Der Betriebshof Britz (Britz, Gradestraße) wurde ebenfalls für die Straßenbahn am 01.10.1966 geschlossen. Dieser Betriebshof beherbergte bis kurz vor seiner Schließung die komplette Linie 47. Nach seiner Schließung wurden 37 Wagen vom Betriebshof Britz über die 11 km lange Betriebsstrecke zum Betriebshof Charlottenburg überführt. Anschließend wurde die 11 km lange Betriebsstrecke stillgelegt und man begann als erstes mit dem Abbau der Gleise am Breitscheidplatz.</span></p></body></html>'),0,0,'2012-07-01 13:56:48');
