INSERT INTO Comments VALUES(269,unistr('02.10.1967\u000aLetzter Betriebstag der Straßenbahn bei der BVG-West'),'55','1967/10/02','["55"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">02.10.1967</span><br />Letzter Betriebstag der Straßenbahn bei der BVG-West</p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Am Montagmorgen, des 02.10.67 erfolgte zur großen Verabschiedung, ein aus 10 Wagen bestehender Wagenkorso. Die Abschiedsfahrt fand von Hakenfelde zum Gleisdreieck Richard-Wagner-Platz und dann weiter zum Betriebshof Charlottenburg statt. Wie auch beim 100-jährigen Jubiläum am 22.07.1965, fuhren auch diesmal wieder Museumswagen im Schlepp mit.Der letzte Westberliner Straßenbahnbetriebshof Char (Charlottenburg, Königin-Elisabeth-Straße) wurde ebenfalls für die Straßenbahn am 02.10.1967 geschlossen.</span> </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Nach der Stillegung am 02.10.1967 fanden noch diverse Überführungsfahrten vom Betriebshof Charlottenburg zum Betriebshof Moabit statt, da dort die Wagen verschrottet wurden.</span></p>\u000a<p align="justify" style="-qt-paragraph-type:empty; margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" width="834" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td width="70" style=" vertical-align:top;"></td></tr></table></body></html>'),0,0,'2012-07-01 13:56:48');
