INSERT INTO Comments VALUES(315,'31.03.1972 Linienänderung Linie 86','86','1972/03/31','["86"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''MS Shell Dlg 2''; font-size:8.25pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-weight:600;">31.03.1972</span><span style=" font-size:8pt;"><br />Linienänderung Linie 86 </span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:8pt; font-style:italic;">Die Fahrten zur Endstelle Mahlsdorf-Süd (samstags und sonntags) verkehrten von 1972 bis 1976 nur während des Sommerfahrplans (April bis September/Oktober). Im Winterfahrplan verkehrte die Linie 86 täglich zwischen Bf. Köpenick und Alt-Schmöckwitz.</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-weight:600; color:#ff0000;">Mahlsdorf-Süd</span><span style=" color:#ff0000;"> - Mahlsdorfer Straße</span> - (Hirtestraße - Stellingdamm -)<span style=" font-weight:600;"> S-Bf. Köpenick</span> - Bahnhofstraße - Lindenstraße - Dammbrücke - &upAlt-Köpenick - &upKirchstraße - &upKietzer Straße - &upGrünstraße - Lange Brücke - Grünauer Straße - Regattastraße - Wassersportallee - S-Bf. Grünau - Grünauer Forst - Regattastraße - Sportpromenade - Vetschauer Allee - Berliner Straße - <span style=" font-weight:600;">Alt-Schmöckwitz</span><br /><span style=" font-style:italic; color:#ff0000;">samstags und sonntags Mahlsdorf-Süd - Alt-Schmöckwitz (nur Sommerfahrplan)</span></p></body></html>'),0,0,'2012-07-01 13:56:48');
