INSERT INTO Comments VALUES(317,unistr('13.01.1986\u000aSperrung Alte Schönhauser Straße'),'49','1986/01/13','["49"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">13.01.1986</span><br />Sperrung Alte Schönhauser Straße</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-weight:600;">Buchholz, KIrche</span> - &upGravensteinstraße - &upElfenallee - &upParkstraße - Hauptstraße - Berliner Straße - Pasewalker Straße - Prenzlauer Chaussee - S-Bf. Pankow-Heinersdorf - Bleicheroder Straße - Stiftsweg - Johannes-R.-Becher-Straße - Berliner Straße - Schönhauser Allee - Kastanienallee - Weinbergsweg - Rosenthaler Platz - Rosenthaler Straße - Hackescher Markt - &upNeue Promenade - &upKleine Präsidentenstraße - <span style=" color:#ff0000;">Oranienburger Straße - Chausseestraße - </span><span style=" font-weight:600; color:#ff0000;">Stadion der Weltjugend</span></p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(318,'31.03./01.04.1973 Neuordnung des Nachtverkehrs','120','1973/04/01','["120"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">31.03./01.04.1973</span><br />Neuordnung des Nachtverkehrs </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Die zum Teil als 24h-Linien betrieben Tageslinien verkehrten ab 31.03.1973 nur noch bis ca. 00:00 Uhr. Danach wurde ein neues Nachtnetz in Betrieb genommen, die durch dreistellige Liniennummern gekennzeichnet waren. Bei der Straßenbahn wurden nur noch drei Linien im Nachtverkehr betrieben, die im 30-Minuten-Takt verkehrten. Ab den 1980er Jahren wurden weitere Nachtstraßenbahnlinien in Betrieb genommen.</span> </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Geplant war die Einführung des neuen Nachtnetzes zum 01.11.1972, wurde aber noch einmal zum 01.04.1973 verschoben. Während dieser Zeit verkehrten weiterhin die Linien 3, 4, 17, 46, 63, 72, 73, 83, 84, 86, 87, 97, 98 und 99 im Nachtverkehr.</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-weight:600; color:#ff0000;">Rosenthal</span><span style=" color:#ff0000;"> - Quickborner Straße - Wilhelmsruher Damm - Friedrich-Engels-Straße - Kurt-Fischer-Platz - Grabbeallee - Schönholzer Straße - Johannes-R.-Becher-Straße - Stiftsweg - Bleicheroder Straße - S-Bf. Pankow-Heinersdorf - Prenzlauer Chaussee - Pasewalker Straße - Berliner Straße - Hauptstraße - &upParkstraße - &upElfenallee - &upGravensteinstraße - </span><span style=" font-weight:600; color:#ff0000;">Buchholz, KIrche</span></p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(319,'31.03./01.04.1973 Neuordnung des Nachtverkehrs','123','1973/04/01','["123"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">31.03./01.04.1973</span><br />Neuordnung des Nachtverkehrs </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Die zum Teil als 24h-Linien betrieben Tageslinien verkehrten ab 31.03.1973 nur noch bis ca. 00:00 Uhr. Danach wurde ein neues Nachtnetz in Betrieb genommen, die durch dreistellige Liniennummern gekennzeichnet waren. Bei der Straßenbahn wurden nur noch drei Linien im Nachtverkehr betrieben, die im 30-Minuten-Takt verkehrten. Ab den 1980er Jahren wurden weitere Nachtstraßenbahnlinien in Betrieb genommen.</span> </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Geplant war die Einführung des neuen Nachtnetzes zum 01.11.1972, wurde aber noch einmal zum 01.04.1973 verschoben. Während dieser Zeit verkehrten weiterhin die Linien 3, 4, 17, 46, 63, 72, 73, 83, 84, 86, 87, 97, 98 und 99 im Nachtverkehr.</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-weight:600; color:#ff0000;">S-Bf. Mahlsdorf</span><span style=" color:#ff0000;"> - Treskowstraße - Hönower Straße - Hultschiner Damm - Mahlsdorfer Straße - S-Bf. Köpenick - Bahnhofstraße - Lindenstraße - Dammbrücke - &upAlt-Köpenick - &upGrünstraße - &upKirchstraße - Kietzer Straße - Müggelheimer Straße - Wendenschloßstraße - </span><span style=" font-weight:600; color:#ff0000;">Wendenschloß </span></p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(320,'31.03./01.04.1973 Neuordnung des Nachtverkehrs','124','1973/04/01','["124"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">31.03./01.04.1973</span><br />Neuordnung des Nachtverkehrs </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Die zum Teil als 24h-Linien betrieben Tageslinien verkehrten ab 31.03.1973 nur noch bis ca. 00:00 Uhr. Danach wurde ein neues Nachtnetz in Betrieb genommen, die durch dreistellige Liniennummern gekennzeichnet waren. Bei der Straßenbahn wurden nur noch drei Linien im Nachtverkehr betrieben, die im 30-Minuten-Takt verkehrten. Ab den 1980er Jahren wurden weitere Nachtstraßenbahnlinien in Betrieb genommen.</span> </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Geplant war die Einführung des neuen Nachtnetzes zum 01.11.1972, wurde aber noch einmal zum 01.04.1973 verschoben. Während dieser Zeit verkehrten weiterhin die Linien 3, 4, 17, 46, 63, 72, 73, 83, 84, 86, 87, 97, 98 und 99 im Nachtverkehr.</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-weight:600; color:#ff0000;">Rahnsdorf</span><span style=" color:#ff0000;"> - Fürstenwalder Damm - S-Bf. Friedrichshagen - Bölschestraße - Müggelseedamm - Fürstenwalder Damm - Bellevuestraße - Seelenbinderstraße - Bahnhofstraße - Lindenstraße - Dammbrücke - &upAlt-Köpenick - &upKirchstraße - &upKietzer Straße - &upGrünstraße - Lange Brücke - Grünauer Straße - Regattastraße - Wassersportallee - S-Bf. Grünau - Grünauer Forst - Regattastraße - Sportpromenade - Vetschauer Allee - Berliner Straße - </span><span style=" font-weight:600; color:#ff0000;">Alt-Schmöckwitz</span><span style=" color:#ff0000;"><br /></span><span style=" font-style:italic; color:#ff0000;">nur drei Fahrten nach Rahnsdorf, sonst nur bis S-Bf. Friedrichshagen</span></p></body></html>'),0,0,'2012-07-01 13:56:48');
