INSERT INTO Comments VALUES(332,unistr('31.03.1975\u000aInbetriebnahme Linie 14'),'14','1975/03/31','["14"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">31.03.1975<br />Inbetriebnahme Linie 14</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-weight:600; color:#ff0000;">Hohenschönhausen, Degnerstraße</span><span style=" color:#ff0000;"> - Degnerstraße - Berliner Straße - Hohenschönhauser Straße - Oderbruchstraße - Leninallee - Dimitroffstraße - </span><span style=" font-weight:600; color:#ff0000;">Artur-Becker-Straße</span><span style=" color:#ff0000;"><br /></span><span style=" font-style:italic; color:#ff0000;">verkehrt nur im Berufsverkehr</span></p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(333,unistr('09.08.1975\u000aLinienänderung Linie 25E (nur Wochenende/Bäderverkehr)'),'1127','1975/08/09','["25E"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">09.08.1975</span><br />Linienänderung Linie 25E (nur Wochenende/Bäderverkehr)</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-weight:600; color:#ff0000;">Rahnsdorf</span><span style=" color:#ff0000;"> - Fürstenwalder Damm - </span><span style=" font-weight:600; color:#ff0000;">S-Bf. Friedrichshagen</span><span style=" color:#ff0000;"><br /></span><span style=" font-style:italic; color:#ff0000;">verkehrt nur am Wochenende in den Sommermonaten bei Bedarf</span></p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(334,unistr('01.09.1975\u000aSperrung Grünauer Straße, Regattastraße'),'86','1975/09/01','["86"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">01.09.1975</span><br />Sperrung Grünauer Straße, Regattastraße </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Der Streckenabschnitt Grünauer Straße und Regattastraße wurde ab 01.09.1975 wegen dem zweigleisigen Umbau bis 24.12.1975 gesperrt. Die Linie 86 verkehrte während dieser Zeit komplett mit Omnibusse.</span></p>\u000a<p align="justify" style="-qt-paragraph-type:empty; margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; font-style:italic;"><br /></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" color:#ff0000;">entfällt</span></p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(335,unistr('01.11.1975\u000aStilllegung Lichtenberger Brücke, Straße der Befreiung'),'15','1975/11/01','["15"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">01.11.1975</span><br />Stilllegung Lichtenberger Brücke, Straße der Befreiung </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Da der Autoverkehr auch in Ostberlin immer mehr zunahm, aber die Brücke am Bahnhof Lichtenberg dem nicht mehr gewachsen war und die Straße der Befreiung mehr Fahrspuren bekommen sollte, wurde eine neue Trasse für die Straßenbahn ab der Kreuzung Herzbergstraße/Siegfriedstraße über das Herzberggelände und dann rechts in die neue Rhinstraße über den Bahnhof Friedrichsfelde-Ost bis zur Kreuzung Straße der Befreiung/Rhinstraße neu gebaut.</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-weight:600; color:#ff0000;">Hackescher Markt</span><span style=" color:#ff0000;"> - Rosenthaler Straße - Neue Schönhauser Straße - Alte Schönhauser Straße - Wilhelm-Pieck-Straße - Mollstraße</span> - Leninallee - Karl-Lade-Straße - Herzbergstraße - Siegfriedstraße - <span style=" font-weight:600; color:#ff0000;">Lichtenberg, Betriebshof</span></p></body></html>'),0,0,'2012-07-01 13:56:48');
INSERT INTO Comments VALUES(336,unistr('01.11.1975\u000aStilllegung Lichtenberger Brücke, Straße der Befreiung \u000a'),'1128','1975/11/01','["17.1"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">01.11.1975</span><br />Stilllegung Lichtenberger Brücke, Straße der Befreiung </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Da der Autoverkehr auch in Ostberlin immer mehr zunahm, aber die Brücke am Bahnhof Lichtenberg dem nicht mehr gewachsen war und die Straße der Befreiung mehr Fahrspuren bekommen sollte, wurde eine neue Trasse für die Straßenbahn ab der Kreuzung Herzbergstraße/Siegfriedstraße über das Herzberggelände und dann rechts in die neue Rhinstraße über den Bahnhof Friedrichsfelde-Ost bis zur Kreuzung Straße der Befreiung/Rhinstraße neu gebaut.</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-weight:600; color:#ff0000;">Stadion der Weltjugend</span><span style=" color:#ff0000;"> - Chausseestraße - Invalidenstraße - Brunnenstraße - Rosenthaler Platz</span> - Wilhelm-Pieck-Straße - Mollstraße - Leninallee - Roederstraße - Herzbergstraße - Siegfriedstraße - <span style=" font-weight:600; color:#ff0000;">Lichtenberg, Betriebshof</span></p></body></html>'),0,0,'2012-07-01 13:56:48');
