INSERT INTO Comments VALUES(363,unistr('18.01.1988\u000aFreigabe Alte Schönhauser Straße\u000aSperrung Invalidenstraße'),'20','1988/01/18','["20"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">18.01.1988</span><br />Freigabe Alte Schönhauser Straße<br />Sperrung Invalidenstraße</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Nach zweijähriger Bauzeit wurde die Alte Schönhauser Straße wieder für den Straßenbahnverkehr freigegeben. Durch die gleichzeitige Sperrung der Invalidenstraße endeten die Linien 20 und 71 weiterhin am U-Bf. Rosa-Luxemburg-Platz. Die veränderte Linienführungen der Linien 70 und 72 wurden dauerhaft beibehalten.</span></p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-weight:600;">Bf. Bln.-Lichtenberg </span>- Gudrunstraße - Siegfriedstraße - Herzbergstraße - Ho-Chi-Minh-Straße - Lichtenberger Straße - Klement-Gottwald-Allee - Antonplatz - Langhansstraße - Prenzlauer Promenade - Prenzlauer Allee - Wilhelm-Pieck-Straße - <span style=" font-weight:600;">U-Bf. Rosa-