INSERT INTO Comments VALUES(371,unistr('02.07.1980\u000aInbetriebnahme Gleisschleife Altglienicke, Am Falkenberg'),'84','1980/07/02','["84"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">02.07.1980</span><br />Inbetriebnahme Gleisschleife Altglienicke, Am Falkenberg </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Mit Inbetriebnahme der Gleisschleife Altglienicke, Am Falkenberg wurde die letzte Kuppelendstelle in Berlin aufgegeben. Bis zur Inbetriebnahme verkehrten auf der Linie 84 ausschlißlich nur Zweirichtungszüge. Baustellenbedingt wurden auch später Kuppelendstellen kurzfristig eingerichtet.</span></p>\u000a<p align="justify" style="-qt-paragraph-type:empty; margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; font-style:italic;"><br /></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-weight:600; color:#ff0000;">Altglienicke, Am Falkenberg </span>- Am Falkenberg - Grünauer Straße - Köpenicker Straße - Gelände westl. der Bahn - S-Bf. Adlershof - Rudower Chaussee - Dörpfeldtstraße - Ottomar-Geschke-Straße - Oberspreestraße - Lange Brücke - &upGrünstraße - &upKirchstraße - &upAlt-Köpenick - Dammbrücke - Lindenstraße - Bahnhofstraße - Seelenbinderstraße - Bellevuestraße - Berliner Straße - Fürstenwal