INSERT INTO Comments VALUES(402,unistr('21.12.1984\u000aInbetriebnahme Strecke Gehrenseestraße - Zingster Straße'),'63','1984/12/21','["63"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">21.12.1984<br />Inbetriebnahme Strecke Gehrenseestraße - Zingster Straße<br /></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" width="834" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td colspan="2" style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><img src="http://www.berlin-straba.de/images/Neubautrassen/1984-12-21_Zingsterstr_800px.jpg" width="800" height="113" style="vertical-align: top;" /> </p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p></td></tr>\u000a<tr>\u000a<td width="70" style=" vertical-align:top;">\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td style=" vertical-align:top;">\u000a<p align="justify" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-weight:600; color:#ff0000;">Hohenschönhausen, Zingster Straße</span><span style=" color:#ff0000;"> - Zingster Straße - Rüdickenstraße - Wartenberger Straße</span> - Hauptstraße - Berliner Straße - Hohenschönhauser Straße - Oderbruchstraße - Leninallee - Mollstraße - Wilhelm-Pieck-Straße - Alte Schönhauser Straße - Neue Schönhauser Straße - Rosenthaler Straße - Hackescher Markt - &upNeue Promenade - &upKleine Präsidentenstraße - Oranienburger Straße - Chausseestraße - <span style=" font-weight:600;">Stadion der Weltjugend</span><br /><span style=" font-style:italic;">montags bis freitags ab 20:00 Uhr, sonnabends und sonntags nur Zingster Straße - Hackescher Markt</span></p></td>\u000a<td style=" vertical-align:top;"></td></tr>\u000a<tr>\u000a<td style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Die Neubautrasse wurde Anfangs nur mit KT4D befahren, sodass die Linie 70 auf KT4D umgestellt wurde. Da Ende 1984 noch nicht ausreichend KT4D''s zur Verfügung standen, verkehrte für ca. 2-3 Monate die Linie 20 (Bf. Bln.-Lichtenberg - Hackescher Markt) wieder mit TE doppelt behangen (TE/BE/BE). Nach dem weitere KT4D''s geliefert wurden, konnte die Linie 20 wieder auf KT4D umgestellt werden.</span></p></td>\u000a<td style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"> </p></td></tr></table></td>\u000a<td width="754" style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"> </p></td></tr></table></body></html>'),0,0,'2012-07-01 13:56:48');
