INSERT INTO Comments VALUES(446,unistr('15.12.1987\u000aSperrung Friedrich-Engels-Straße\u000a\u000aWegen der Erneuerung der eingleisigen Strecken, inklusive der Ausweichstellen, wurde die Friedrich-Engels-Straße '),'22','1987/12/15','["22"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">15.12.1987</span><br />Sperrung Friedrich-Engels-Straße </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Wegen der Erneuerung der eingleisigen Strecken, inklusive der Ausweichstellen, wurde die Friedrich-Engels-Straße ab 15.12.1987 für den Straßenbahnverkehr gesperrt.</span></p>\u000a<p align="justify" style="-qt-paragraph-type:empty; margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; font-style:italic;"><br /></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" color:#ff0000;">entfällt</span></p></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(447,unistr('18.01.1988\u000aFreigabe Alte Schönhauser Straße\u000aSperrung Invalidenstraße'),'11','1988/01/18','["11"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">18.01.1988</span><span style=" font-weight:600; font-style:italic;"><br /></span>Freigabe Alte Schönhauser Straße<br />Sperrung Invalidenstraße</p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Nach zweijähriger Bauzeit wurde die Alte Schönhauser Straße wieder für den Straßenbahnverkehr freigegeben. Durch die gleichzeitige Sperrung der Invalidenstraße endeten die Linien 20 und 71 weiterhin am U-Bf. Rosa-Luxemburg-Platz. Die veränderte Linienführungen der Linien 70 und 72 wurden dauerhaft beibehalten.</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-weight:600;">Biesdorf, Elisabethstraße</span> - Allee der Kosmonauten - Bruno-Leuschner-Straße - Marzahner Promenade - S-Bf. Bln.-Marzahn - Leninallee - Altenhofer Straße - Berliner Straße - Hohenschönhauser Straße - Oderbruchstraße - Leninallee - Mollstraße - Wilhelm-Pieck-Straße - <span style=" color:#ff0000;">Alte Schönhauser Straße - Neue Schönhauser Straße - Rosenthaler Straße - Hackescher Markt - Oranienburger Straße - Friedrichstraße</span> - Chausseestraße - <span style=" font-weight:600;">Stadion der Weltjuge