INSERT INTO Comments VALUES(475,unistr('06.12.1988\u000aSperrung Altglienicke, Am Falkenberg - S-Bf. Adlershof '),'84','1988/12/06','["84"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">06.12.1988</span><br />Sperrung Altglienicke, Am Falkenberg - S-Bf. Adlershof </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Nach damaligen Planungen sollte die Strecke Am Falkenberg - S-Bf. Adlershof, aufgrund des schlechten Gleiszustandes, stillgelegt werden. Durch Proteste wurde dieser Streckenabschnitt saniert, sodass ab 02.04.1989 die Strecke wieder freigegeben wurde. Baustellenbedingt mussten auf der Linie 84 wieder Zweirichtungszüge (TZ69/BZ69) eingesetzt werden, da die Endstelle S-Bf. Adlershof eine Kuppelendstelle war.</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#ff0000;">S-Bf. Adlershof </span><span style=" font-size:10pt;">- Rudower Chaussee - Dörpfeldtstraße - Ottomar-Geschke-Straße - Oberspreestraße - Lange Brücke - &upGrünstraße - &upKirchstraße - &upAlt-Köpenick - Dammbrücke - Lindenstraße - Bahnhofstraße - Seelenbinderstraße - Bellevuestraße - Berliner Straße - Fürstenwalder Damm - S-Bf. Friedrichshagen - Bölschestraße - Müggelseedamm - </span><span style=" font-size:10pt; font-weight:600;">Friedrichshagen, Wasserwerk</span></p></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(476,unistr('16.12.1988\u000aLinienänderung Linie 18E'),'1016','1988/12/16','["18E"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">16.12.1988</span><br />Linienänderung Linie 18E</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600;">Ahrensfelde bzw. Marzahn, Henneckestraße</span><span style=" font-size:10pt;"> - Lea-Grundig-Straße - Bruno-Leuschner-Straße - Allee der Kosmonauten - Fachkrankenhaus - Herzbergstraße - Karl-Lade-Straße - Leninallee - Leninallee/Dimitroffstraße<br /></span><span style=" font-size:10pt; font-style:italic; color:#ff0000;">im Berufsverkehr zwischen Ahrensfelde und Leninallee/Dimitroffstraße, die Fahrten zur Mollstraße/Hans-Beimler-Straße entfallen</span></p></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(477,unistr('02.04.1989\u000aWiederinbetriebnahme Altglienicke, Am Falkenberg - S-Bf. Adlershof '),'84','1989/04/02','["84"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">02.04.1989<br />Wiederinbetriebnahme Altglienicke, Am Falkenberg - S-Bf. Adlershof </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Der Einsatz von Zweirichtungsfahrzeugen auf der Linie 84 war ab 02.04.1989 nicht mehr notwendig.</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Altglienicke, Am Falkenberg</span><span style=" font-size:10pt; color:#ff0000;"> - Am Falkenberg - Grünauer Straße - Köpenicker Straße - Gelände westl. der Bahn</span><span style=" font-size:10pt;"> - S-Bf. Adlershof - Rudower Chaussee - Dörpfeldtstraße - Ottomar-Geschke-Straße - Oberspreestraße - Lange Brücke - &upGrünstraße - &upKirchstraße - &upAlt-Köpenick - Dammbrücke - Lindenstraße - Bahnhofstraße - Seelenbinderstraße - Bellevuestraße - Berliner Straße - Fürstenwalder Damm - S-Bf. Friedrichshagen - Bölschestraße - Müggelseedamm - </span><span style=" font-size:10pt; font-weight:600;">Friedrichshagen, Wasserwerk</span></p></body></html>'),0,0,'2012-07-01 13:56:49');
