INSERT INTO Comments VALUES(499,unistr('12./13.05. bis 14./15.05.1989\u000aFDJ-Pfingsttreffen (Veränderungen im Nachtverkehr)'),'3','1989/05/12','["3"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">12./13.05. bis 14./15.05.1989</span><br />FDJ-Pfingsttreffen (Veränderungen im Nachtverkehr)</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Wegen dem FDJ-Pfingsttreffen in Berlin wurde der Nachtverkehr in den Nächten vom 12./13.05.1989 bis 14./15.05.1989 wie folgt verändert. Alle genanten Linien im Nachtverkehr verkehrten im 30-Minuten-Takt. Ab der Nacht 15./16.05.1989 fuhren alle Nachtlinien wie vor dem FDJ-Pfingsttreffen.</span></p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; font-size:9pt; font-style:italic;"><br /></p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; font-size:9pt; font-style:italic;"><br /></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td bgcolor="#ffffff" style=" vertical-align:top;">\u000a<p align="center" st