INSERT INTO Comments VALUES(561,unistr('18.11.1989\u000aInbetriebnahme Linien 3E und 4E '),'1022','1989/11/18','["3E"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">18.11.1989<br />Inbetriebnahme Linien 3E und 4E </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Wegen dem erhöhten Fahrgastaufkommen auf den Linien 3 und 4, aufgrund der Grenzöffnung vom 09.11.1989, wurden die Linien 3 und 4 an den Wochenenden durch die Linien 3E und 4E verstärkt.</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Bornholmer Straße</span><span style=" font-size:10pt; color:#ff0000;"> - Bornholmer Straße - Wisbyer Straße - Prenzlauer Promenade - Langhansstraße - Antonplatz - Klement-Gottwald-Allee - Rennbahnstraße -</span><span style=" font-size:10pt; font-weight:600; color:#ff0000;"> Weißensee, Pasedagplatz</span></p></body></html>'),0,0,'2012-07-01 13:56:49');
