INSERT INTO Comments VALUES(575,'','1137','1990/04/24','["TRO"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">24.04.1990</span><br />Letzter Einsatztag für die Güterstraßenbahn (TRO Niederschönhausen - Oberschöneweide) </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Am 24.04.1990 fuhr die letzte Güterstraßenbahn zwischen TRO Niederschönhausen und Oberschöneweide. Diese Fahrten wurden ab 28.06.1982 mit einem Arbeitstriebwagen, sowie Güterloren durchgeführt.</span></p></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(577,unistr('28.06.1982\u000aInbetriebnahme Güterstraßenbahnverkehr für TRO'),'1137','1982/06/29','["TRO"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">28.06.1982</span><br />Inbetriebnahme Güterstraßenbahnverkehr für TRO </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Wegen Kraftstoffeinsparung verkehrt zwischen der Gleisschleife Niederschönhausen, Schillerstraße und Oberschöneweide, Wilhelminenhofstraße eine Güterstraßenbahnlinie, bestehend aus einem Rekoarbeitstriebwagen und zwei Güterloren. Die Linie verkehrt über Kurt-Fischer-Platz - Pankow Kirche - S-Bf. Bln.-Pankow - U-Bf. Pankow (Vinetastraße) - Bornholmer Straße - Gleisschleife Björnsonstraße - Bornholmer Straße - Wisbyer Straße - Langhansstraße - Klement-Gottwald-Allee - Lichtenberger Straße - Ho-Chi-Minh-Straße - Herzbergstraße - Fachkrankenhaus - Rhinstraße - Am Tierpark - Hermann-Duncker-Straße - Edisonstraße.</span></p></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(578,unistr('01.06.1983\u000aInbetriebnahme Güterstraßenbahnverkehr für VEB Sero '),'1138','1983/06/01','["SERO"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">01.06.1983</span><br />Inbetriebnahme Güterstraßenbahnverkehr für VEB Sero </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Nach Einbau von Ausweichgleisen bzw. Gleisanschlüssen am Hultschiner Damm und der Günauer Straße verkehrt eine weitere Güterstraßenbahnlinie zwischen Mahlsdorf - Hultschiner Damm und Hafen Grünauer Straße für den VEB Sekundärrohstoffe (SERO).</span></p></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(579,unistr('11.05.1990\u000aLetzter Einsatztag für die Güterstraßenbahn (SERO Mahlsdorf - Grünauer Straße) '),'1138','1990/11/05','["SERO"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">11.05.1990</span><br />Letzter Einsatztag für die Güterstraßenbahn (SERO Mahlsdorf - Grünauer Straße) </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-weight:600; font-style:italic;">Am 11.05.1990 fuhr die letzte Güterstraßenbahn zwischen SERO Mahlsdorf und Grünauer Straße. Diese Fahrten wurden ab 01.06.1983 mit einem Arbeitstriebwagen, sowie Güterloren durchgeführt.</span><span style=" font-size:9pt; font-weight:600; font-style:italic;"> </span></p></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(580,unistr('10.11.1990\u000aWiederinbetriebnahme Gleisschleife Stadion der Weltjugend\u000aLinienänderung Linie 108'),'24','1990/11/10','["24"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">10.11.1990</span><br />Wiederinbetriebnahme Gleisschleife Stadion der Weltjugend<br />Linienänderung Linie 108</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600;">Weißensee, Pasedagplatz</span><span style=" font-size:10pt;"> - Rennbahnstraße - Klement-Gottwald-Allee - Greifswalder Straße - Hans-Beimler-Straße - Mollstraße - Wilhelm-Pieck-Straße - Alte Schönhauser Straße - Neue Schönhauser Straße - Rosenthaler Platz - Hackescher Markt - Oranienburger Straße - Friedrichstraße - Chausseestraße - </span><span style=" font-size:10pt; font-weight:600;">Stadion der Weltjugend</span></p></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(581,unistr('10.11.1990\u000aWiederinbetriebnahme Gleisschleife Stadion der Weltjugend\u000aLinienänderung Linie 108'),'108','1990/11/10','["108"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">10.11.1990</span><br />Wiederinbetriebnahme Gleisschleife Stadion der Weltjugend<br />Linienänderung Linie 108</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Falkenberg</span><span style=" font-size:10pt; color:#ff0000;"> - Falkenberger Chaussee - Prerower Platz - Rüdickenstraße </span><span style=" font-size:10pt;">- Gehrenseestraße - Hauptstraße - Konrad-Wolf-Straße - Hohenschönhauser Straße - Oderbruchstraße - Leninallee - Mollstraße - Wilhelm-Pieck-Straße - Alte Schönhauser Straße - Neue Schönhauser Straße - Rosenthaler Straße - Hackescher Markt - Oranienburger Straße - Friedrichstraße - Chausseestraße -</span><span style=" font-size:10pt; font-weight:600;"> Stadion der Weltjugend</span></p></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(582,unistr('13./14.11.1990\u000aStraßenschlacht Mainzer Straße '),'13','1990/11/13','["13"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">13./14.11.1990</span><br />Straßenschlacht Mainzer Straße </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">In der Nacht vom 13. zum 14.11.1990 wurden ein Zug der Linie 13 vom Betriebshof Niederschönhausen als Straßenbarrikade mißbraucht. Es wurde der Triebwagen 217 106, sowie die beiden Beiwagen 267 034 und 267 140 stark beschädigt.</span></p></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(583,unistr('01.05.1991\u000aInbetriebnahme Strecke Riesaer Straße - Marzahn, Betriebshof '),'6','1991/05/01','["6"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">01.05.1991</span><br />Inbetriebnahme Strecke Riesaer Straße - Marzahn, Betriebshof </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-weight:600; font-style:italic;">Am 01.05.1991 wurde die letzte Neubaustrecke, mit einer Länge von 4,5 km, im neuen Stadtbezirk Berlin-Hellersdorf zwischen dem Betriebshof Marzahn und Riesaer Straße, unter BVB-Regie in Betrieb genommen. </span></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" width="834" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td colspan="2" style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><img src="http://www.berlin-straba.de/images/Neubautrassen/1991-05-01_Riesaerstr_800px.jpg" width="800" height="189" style="vertical-align: top;" /></p></td></tr></table>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Hellersdorf, Riesaer Straße</span><span style=" font-size:10pt; color:#ff0000;"> - Riesaer Straße - Stendaler Straße - Zossener Straße</span><span style=" font-size:10pt;"> - Leninallee - Bruno-Leuschner-Straße - Marzahner Promenade - S-Bf. Bln.-Marzahn - Leninallee - Altenhofer Straße - Konrad-Wolf-Straße - Hohenschönhauser Straße - Oderbruchstraße - Leninallee - Mollstraße - Wilhelm-Pieck-Straße - Rosenthaler Platz - Brunnenstraße - Invalidenstraße - Chausseestraße - </span><span style=" font-size:10pt; font-weight:600;">Stadion der Weltjugend</span></p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; font-size:10pt; font-weight:600;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-weight:600; font-style:italic;">Ab 19.04.1991 erfolgten erste Probefahrten auf dieser Neubaustrecke zwischen dem Betriebshof Marzahn und Riesaer Straße.</span><span style=" font-size:9pt; font-weight:600; font-style:italic;"> </span><span style=" font-size:9pt; font-weight:600; font-style:italic;">Am 26.04.1991 erfolgte die Abnahme der Strecke Betriebshof Marzahn - Riesaer Straße durch die Technische Aufsichtsbehörde und am 30.04.1991 fand die Eröffnungsfeier gegen ca. 15:30 Uhr an der Haltestelle Landsberger Chaussee/Zossener Straße in Richtung Riesaer Straße statt. Der Eröffnungszug wurde aus dem T6A2 / T6A2 / B6A2 Großzug (218 177-8 / 218 178-6 / 268 244-2) gebildet.</span><span style=" font-size:9pt; font-weight:600; font-style:italic;"> </span></p></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(584,unistr('01.05.1991\u000aInbetriebnahme Strecke Riesaer Straße - Marzahn, Betriebshof '),'10','1990/05/01','["10"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">01.05.1991</span><br />Inbetriebnahme Strecke Riesaer Straße - Marzahn, Betriebshof </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-weight:600; font-style:italic;">Am 01.05.1991 wurde die letzte Neubaustrecke, mit einer Länge von 4,5 km, im neuen Stadtbezirk Berlin-Hellersdorf zwischen dem Betriebshof Marzahn und Riesaer Straße, unter BVB-Regie in Betrieb genommen. </span></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" width="834" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td colspan="2" style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><img src="http://www.berlin-straba.de/images/Neubautrassen/1991-05-01_Riesaerstr_800px.jpg" width="800" height="189" style="vertical-align: top;" /></p></td></tr></table>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Hellersdorf, Riesaer Straße </span><span style=" font-size:10pt; color:#ff0000;">- Riesaer Straße - Stendaler Straße - Zossener Straße</span><span style=" font-size:10pt;"> - Leninallee - Allee der Kosmonauten - Rhinstraße - Hauptstraße - Suermondtstraße - Buschallee - Klement-Gottwald-Allee - Rennbahnstraße - </span><span style=" font-size:10pt; font-weight:600;">Weißensee, Pasedagplatz</span></p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; font-size:10pt; font-weight:600;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-weight:600; font-style:italic;">Ab 19.04.1991 erfolgten erste Probefahrten auf dieser Neubaustrecke zwischen dem Betriebshof Marzahn und Riesaer Straße.</span><span style=" font-size:9pt; font-weight:600; font-style:italic;"> </span><span style=" font-size:9pt; font-weight:600; font-style:italic;">Am 26.04.1991 erfolgte die Abnahme der Strecke Betriebshof Marzahn - Riesaer Straße durch die Technische Aufsichtsbehörde und am 30.04.1991 fand die Eröffnungsfeier gegen ca. 15:30 Uhr an der Haltestelle Landsberger Chaussee/Zossener Straße in Richtung Riesaer Straße statt. Der Eröffnungszug wurde aus dem T6A2 / T6A2 / B6A2 Großzug (218 177-8 / 218 178-6 / 268 244-2) gebildet.</span><span style=" font-size:9pt; font-weight:600; font-style:italic;"> </span></p></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(585,unistr('01.05.1991\u000aInbetriebnahme Strecke Riesaer Straße - Marzahn, Betriebshof \u000a'),'103','1991/05/01','["103"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">01.05.1991</span><br />Inbetriebnahme Strecke Riesaer Straße - Marzahn, Betriebshof </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-weight:600; font-style:italic;">Am 01.05.1991 wurde die letzte Neubaustrecke, mit einer Länge von 4,5 km, im neuen Stadtbezirk Berlin-Hellersdorf zwischen dem Betriebshof Marzahn und Riesaer Straße, unter BVB-Regie in Betrieb genommen.</span><span style=" font-size:9pt; font-weight:600; font-style:italic;"> </span></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" width="834" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td colspan="2" style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><img src="http://www.berlin-straba.de/images/Neubautrassen/1991-05-01_Riesaerstr_800px.jpg" width="800" height="189" style="vertical-align: top;" /></p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600;">Björnsonstraße</span><span style=" font-size:10pt;"> - Bornholmer Straße - Wisbyer Straße - Prenzlauer Promenade - Langhansstraße - Antonplatz - Klement-Gottwald-Allee - Indira-Gandhi-Straße - Altenhofer Straße - Leninallee - S-Bf. Bln.-Marzahn - Marzahner Promenade - Bruno-Leuschner-Straße - Allee der Kosmonauten - Leninallee - </span><span style=" font-size:10pt; color:#ff0000;">Zossener Straße - Stendaler Straße - Riesaer Straße - </span><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Hellersdorf, Riesaer Straße</span></p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; font-weight:600;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Ab 19.04.1991 erfolgten erste Probefahrten auf dieser Neubaustrecke zwischen dem Betriebshof Marzahn und Riesaer Straße.</span><span style=" font-size:9pt; font-style:italic;"> </span><span style=" font-size:9pt; font-style:italic;">Am 26.04.1991 erfolgte die Abnahme der Strecke Betriebshof Marzahn - Riesaer Straße durch die Technische Aufsichtsbehörde und am 30.04.1991 fand die Eröffnungsfeier gegen ca. 15:30 Uhr an der Haltestelle Landsberger Chaussee/Zossener Straße in Richtung Riesaer Straße statt. Der Eröffnungszug wurde aus dem T6A2 / T6A2 / B6A2 Großzug (218 177-8 / 218 178-6 / 268 244-2) gebildet.</span></p></td></tr></table></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(586,unistr('15.05.1991\u000aLinienänderung Linie 72'),'72','1991/05/15','["72"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">15.05.1991</span><br />Linienänderung Linie 72</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Am Steinberg</span><span style=" font-size:10pt;"> - Prenzlauer Promenade - Prenzlauer Allee - Mollstraße - Leninallee - Karl-Lade-Straße - Herzbergstraße - Fachkrankenhausgelände - Allee der Kosmonauten - Bruno-Leuschner-Straße - Lea-Grundig-Straße - Max-Herrmann-Straße - </span><span style=" font-size:10pt; font-weight:600;">Marzahn, Henneckestraße</span><span style=" font-size:10pt;"><br /></span><span style=" font-size:10pt; font-style:italic;">verkehrt nur im Berufsverkehr</span></p></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(587,unistr('02.06.1991\u000aLinienänderungen wegen Wegfall von E-Linien\u000aNeue Liniennummern im Nachtverkehr '),'1019','1991/06/02','["16E"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">02.06.1991</span><br />Linienänderungen wegen Wegfall von E-Linien<br />Neue Liniennummern im Nachtverkehr </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Da im Busnetz ein neues einheitliches Liniennummernsystem bei BVB und BVG eingeführt wurde, mussten auch einige Verstärkerlinien, die mit einem zusätzlichen &quot;E&quot; gekennzeichnet waren, neue Liniennummern erhalten. Die Linie 16E wurde zur Linie 36, die Linie 25E zur Linie 23. Auch die Linie 88 musste in Linie 81 umbenannt werden, da die Liniennummer 88 ab 02.06.1991 der Schöneicher-Rüdersdorfer Straßenbahn zugeteilt wurde. Im Nachtverkehr wurde ein einheitliches Nachtnetz eingeführt, deren Liniennummer ein &quot;N&quot; vorangestellt wurde.</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" color:#ff0000;">entfällt</span></p>\u000a<p align="justify" style="-qt-paragraph-type:empty; margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; font-size:9pt; font-style:italic;"><br /></p></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(588,unistr('02.06.1991\u000aLinienänderungen wegen Wegfall von E-Linien\u000aNeue Liniennummern im Nachtverkehr \u000a'),'23','1991/06/02','["23"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">02.06.1991</span><br />Linienänderungen wegen Wegfall von E-Linien<br />Neue Liniennummern im Nachtverkehr </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Da im Busnetz ein neues einheitliches Liniennummernsystem bei BVB und BVG eingeführt wurde, mussten auch einige Verstärkerlinien, die mit einem zusätzlichen &quot;E&quot; gekennzeichnet waren, neue Liniennummern erhalten. Die Linie 16E wurde zur Linie 36, die Linie 25E zur Linie 23. Auch die Linie 88 musste in Linie 81 umbenannt werden, da die Liniennummer 88 ab 02.06.1991 der Schöneicher-Rüdersdorfer Straßenbahn zugeteilt wurde. Im Nachtverkehr wurde ein einheitliches Nachtnetz eingeführt, deren Liniennummer ein &quot;N&quot; vorangestellt wurde.</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; color:#ff0000;">(Früh-HVZ) </span><span style=" font-size:10pt; font-weight:600; color:#ff0000;">S-Bf. Friedrichshagen</span><span style=" font-size:10pt; color:#ff0000;"> - &upFürstenwalder Damm - &upBölschestraße - &upMüggelseedamm - Fürstenwalder Damm - Bellevuestraße - Seelenbinderstraße - Bahnhofstraße - Lindenstraße - An der Wuhlheide - Weiskopffstraße - Ostendstraße - Wilhelminenhofstraße - Edisonstraße - Brückenstraße - Grünauer Straße - Sterndamm - </span><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Bf. Bln.-Schöneweide</span><span style=" font-size:10pt; color:#ff0000;"><br /></span><span style=" font-size:10pt; color:#008000;">(Nachmittags-HVZ) </span><span style=" font-size:10pt; font-weight:600; color:#008000;">S-Bf. Friedrichshagen</span><span style=" font-size:10pt; color:#008000;"> - &upFürstenwalder Damm - &upBölschestraße - &upMüggelseedamm - Fürstenwalder Damm - Bellevuestraße - Seelenbinderstraße - Bahnhofstraße - Lindenstraße - An der Wuhlheide - Weiskopffstraße - Ostendstraße - Wilhelminenhofstraße - Edisonstraße - Brückenstraße - Grünauer Straße - Sterndamm - </span><span style=" font-size:10pt; font-weight:600; color:#008000;">Bf. Bln.-Schöneweide</span><span style=" font-size:10pt; color:#ff0000;"><br /></span><span style=" font-size:10pt; font-style:italic; color:#ff0000;">verkehrt nur im Berufsverkehr</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Rahnsdorf</span><span style=" font-size:10pt; color:#ff0000;"> - Fürstenwalder Damm - S-Bf. Friedrichshagen - Bölschestraße - Müggelseedamm - </span><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Friedrichshagen, Wasserwerk</span><span style=" font-size:10pt; color:#ff0000;"><br /></span><span style=" font-size:10pt; font-style:italic; color:#ff0000;">verkehrt nur samstags und sonntags in den Sommermonaten bei Bedarf</span></p></body></html>'),0,0,'2012-07-01 13:56:49');
