INSERT INTO Comments VALUES(630,unistr('21.04.1992\u000aSperrung Quickborner Straße '),'22','1992/04/21','["22"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">21.04.1992<br />Sperrung Quickborner Straße </p>\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Da die Endstelle Rosenthal Hauptstraße eine Stumpfendstelle war, mussten auf der Linie 22 Zweirichtungszüge (TZ/BZ) eingesetzt werden.</span></p>\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Rosenthal, Hauptstraße</span><span style=" font-size:10pt;"> - Friedrich-Engels-Straße - Kurt-Fischer-Platz - Grabbeallee - Schönholzer Straße - Johannes-R.-Becher-Straße - Berliner Straße - Schönhauser Allee - Kastanienallee - Zionskirchplatz - Veteranenstraße - Invalidenstraße - Chausseestraße - Oranienburger Tor - Friedrichstraße - Am Weidendamm - Planckstraße - &upClara-Zetkin-Straße - &upGeorgenstraße - Am Kupfergraben - </span><span style=" font-size:10pt; font-weight:600;">Am Kupfergraben</span></p></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(631,unistr('14.10.1995\u000aInbetriebnahme Strecke Bornholmer Straße - Louise-Schroeder-Platz '),'24','1995/10/14','["24"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">14.10.1995</span><br />Inbetriebnahme Strecke Bornholmer Straße - Louise-Schroeder-Platz </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-weight:600; font-style:italic;">Am 14.10.1995 wurde die Neubaustrecke zwischen Bornholmer Straße/Björnsonstraße und Louise-Schroeder-Platz in Betrieb genommen. Dies war nach 28 Jahren wieder die erste Straßenbahnstrecke in den ehemaligen Westeil von Berlin. Der erste Zug, der die Strecke Bornholmer Straße - Osloer Straße befuhr, war der Fahrleitungskontrollwagen 4571 (KT4D) am 30.09.1995.<br />Mit Inbetriebnahme der Neubaustrecke zum Louise-Schroeder-Platz wurde die Endstelle S Bornholmer Straße in Prenzlauer Berg, Björnsonstraße umbenannt. </span></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" width="834" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td colspan="2" style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><img src="http://www.berlin-straba.de/images/Neubautrassen/1995-10-14_Schroederplatz_800px.jpg" width="800" height="125" style="vertical-align: top;" /></p></td></tr>\u000a<tr>\u000a<td width="70" style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-weight:600; color:#ff0000;">Wedding, Louise-Schroeder-Platz</span><span style=" color:#ff0000;"> - Seestraße - Osloer Straße - Bornholmer Straße - Wisbyer Straße - Prenzlauer Promenade - Langhansstraße - Antonplatz - Berliner Allee - Buschallee - </span><span style=" font-weight:600; color:#ff0000;">Weißensee, Hansastraße</span><span style=" color:#ff0000;"><br /></span><span style=" font-style:italic; color:#ff0000;">verkehrt nur montags bis samstags bis ca. 19:00 Uhr</span></p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; color:#ff0000;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Auf der Linie 23 werden nur Wagen vom Typ KT4D-t mod vom Betriebshof Weißensee eingesetzt. Die Linie 24 wird komplett mit Wagen vom Typ GT6N vom Betriebshof Marzahn befahren.</span></p></td>\u000a<td width="754" style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"> </p></td></tr></table></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(632,unistr('01.01.1992\u000aFusion (BVB und BVG zur BVG) \u000a'),'','1992/01/01','[]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">01.01.1992</span><br />Fusion (BVB und BVG zur BVG) </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Die Berliner Verkehrbetriebe Ost (BVB) und West (BVG) fusionierten zu einem Betrieb. Ab 1992 wurde auch für das ehemalige Personal der BVB die westliche Dienstkleidung ausgegeben. Die Farbe der Sakkos änderte sich dadurch von Grau in Blau. Auch an den Straßenbahnfahrzeuge wurde nach und nach das BVG-Wappen an den Fahrzeugen angebracht. </span></p></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(633,unistr('09.01.1992\u000aUmbenennung'),'','1992/01/09','[]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">09.01.1992</span><br />Umbenennung </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Folgende Straßen wurden zum 09.01.1992 umbenannt:</span><span style=" font-size:9pt; font-style:italic;"> </span><span style=" font-size:9pt; font-style:italic;">Die Haltestellen wurden dementsprechend mit umbenannt.</span><span style=" font-size:9pt; font-style:italic;"> </span></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" width="100%" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td bgcolor="#ffff99">\u000a<p align="center" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">Straßenname bis 08.01.1992</p></td>\u000a<td bgcolor="#ffff99">\u000a<p align="center" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">Straßenname ab 09.01.1992</p></td></tr>\u000a<tr>\u000a<td>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Hermann-Duncker-Straße</span></p></td>\u000a<td>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Treskowallee</span></p></td></tr>\u000a<tr>\u000a<td bgcolor="#cccccc">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Ho-Chi-Minh-Straße</span></p></td>\u000a<td bgcolor="#cccccc">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Weißenseer Weg</span></p></td></tr>\u000a<tr>\u000a<td bgcolor="#ffffff">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Jacques-Duclos-Straße</span></p></td>\u000a<td bgcolor="#ffffff">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Möllendorffstraße</span></p></td></tr>\u000a<tr>\u000a<td bgcolor="#cccccc">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Straße der Befreiung</span></p></td>\u000a<td bgcolor="#cccccc">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-style:italic;">Alt-Friedrichsfelde</span></p></td></tr></table></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(636,unistr('02/1992\u000aBVG-Wappen \u000a01.02.1992 Umbenennung\u000a\u000a'),'','1992/02/01','[]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">02/1992</span><br />BVG-Wappen <img src="http://www.berlin-straba.de/images/bvg-symbole/Logo-BVG_klein.jpg" width="37" height="72" style="float: right;" /></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Ab Anfang Februar wurde damit begonnen, die BVG-Wappen auf den Straßenbahnfahrzeugen anzubringen</span><span style=" font-style:italic;">.</span> </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Folgende Straßen wurden zum 01.02.1992 umbenannt:</span><span style=" font-size:9pt; font-style:italic;"> </span><span style=" font-size:9pt; font-style:italic;">Die Haltestellen wurden dementsprechend mit umbenannt.</span><span style=" font-size:9pt; font-style:italic;"> </span></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" width="100%" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td bgcolor="#ffff99">\u000a<p align="center" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">Straßenname bis 31.01.1992</p></td>\u000a<td bgcolor="#ffff99">\