INSERT INTO Comments VALUES(647,unistr('01.01.1993\u000aStilllegung Am Falkenberg, Grünauer Straße, Köpenicker Straße, Gelände westl. der Bahn (Adlershof) '),'84','1993/01/01','["84"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">01.01.1993</span><br />Stilllegung Am Falkenberg, Grünauer Straße, Köpenicker Straße, Gelände westl. der Bahn (Adlershof) </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-weight:600; font-style:italic;">Zum 01.01.1993 wurde der Streckenabschnitt Am Falkenberg - S-Bf. Adlershof endgültig stillgelegt, da die Altglienicker Brücke Baufällig war. Baustellenbedingt mussten auf der Linie 84 wieder Zweirichtungszüge (TZ69/BZ69) eingesetzt werden, da die Endstelle S-Bf. Adlershof eine Kuppelendstelle war.</span><span style=" font-size:9pt; font-weight:600; font-style:italic;"> </span></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" width="834" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td colspan="2" style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><img src="http://www.berlin-straba.de/images/Neubautrassen/z1993-01-01_Altglienicke_800px.jpg" width="800" height="105" style="vertical-align: top;" /><br /><span style=" font-size:10pt; font-weight:600; color:#ff0000;">S-Bf. Adlershof </span><span style=" font-size:10pt;">- Rudower Chaussee - Dörpfeldtstraße - Ottomar-Geschke-Straße - Oberspreestraße - Lange Brücke - &upGrünstraße - &upKirchstraße - &upAlt-Köpenick - Dammbrücke - Lindenstraße - Bahnhofstraße - Seelenbinderstraße - Bellevuestraße - Berliner Straße - Fürstenwalder Damm - S-Bf. Friedrichshagen - Fürstenwalder Damm - </span><span style=" font-size:10pt; font-weight:600;">Rahnsdorf</span></p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p></td></tr>\u000a<tr>\u000a<td width="70" style=" vertical-align:top;"></td>\u000a<td width="754" style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"> </p></td></tr></table></body></html>'),0,0,'2012-07-01 13:56:49');
