INSERT INTO Comments VALUES(695,unistr('02.10.1996\u000aInbetriebnahme Linie 63 '),'63','1996/10/01','["63"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">02.10.1996</span><br />Inbetriebnahme Linie 63 </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Wegen Bauarbeiten verkehrte die Linie 63 vom 04.10.1996 bis zum 14.12.1996 zwischen S Adlershof und Betriebshof Köpenick. Die Verlängerung zum S Köpenick erfolgte zum 15.12.1996</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#ff0000;">S-Bf. Adlershof</span><span style=" font-size:10pt; color:#ff0000;"> - Rudower Chaussee - Dörpfeldtstraße - Ottomar-Geschke-Straße - Oberspreestraße - Lange Brücke - &upGrünstraße - &upKirchstraße - &upAlt-Köpenick - Dammbrücke - Lindenstraße - Bahnhofstraße - </span><span style=" font-size:10pt; font-weight:600; color:#ff0000;">S-Bf. Köpenick</span><span style=" font-size:10pt; color:#ff0000;"> - Stellingdamm - Hirtestraße<br /></span><span style=" font-size:10pt; font-style:italic; color:#ff0000;">verkehrt nur montags bis freitags bis ca. 20:00 Uhr</span></p></body></html>'),0,0,'2012-07-01 13:56:49');
