INSERT INTO Comments VALUES(746,unistr('02.10.1995\u000aInbetriebnahme Gleisschleife S Adlershof '),'60','1995/10/02','["60"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">02.10.1995<br />Inbetriebnahme Gleisschleife S Adlershof </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Durch die Inbetriebnahme der neuen Gleisschleife am S-Bahnhof Adlershof konnte auf der Linie 60 wieder Einrichtungszüge zum Einsatz kommen.</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#ff0000;">S-Bf. Adlershof</span><span style=" font-size:10pt; font-weight:600;"> </span><span style=" font-size:10pt;">- Rudower Chaussee - Dörpfeldtstraße - Ottomar-Geschke-Straße - Oberspreestraße - Lange Brücke - &upGrünstraße - &upKirchstraße - &upAlt-Köpenick - Dammbrücke - Lindenstraße - Bahnhofstraße - Seelenbinderstraße - Bellevuestraße - Berliner Straße - Fürstenwalder Damm - S-Bf. Friedrichshagen - Bölschestraße - Müggelseedamm - </span><span style=" font-size:10pt; font-weight:600;">Friedrichshagen, Wasserwerk</span></p>\u000a<p align="justify" style="-qt-paragraph-type:empty; margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; font-size:10pt;"><br /></p></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(747,unistr('14.10.1995\u000aInbetriebnahme Strecke Bornholmer Straße - Louise-Schroeder-Platz '),'23','1995/10/14','["23"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">14.10.1995</span><br />Inbetriebnahme Strecke Bornholmer Straße - Louise-Schroeder-Platz </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-weight:600; font-style:italic;">Am 14.10.1995 wurde die Neubaustrecke zwischen Bornholmer Straße/Björnsonstraße und Louise-Schroeder-Platz in Betrieb genommen. Dies war nach 28 Jahren wieder die erste Straßenbahnstrecke in den ehemaligen Westeil von Berlin. Der erste Zug, der die Strecke Bornholmer Straße - Osloer Straße befuhr, war der Fahrleitungskontrollwagen 4571 (KT4D) am 30.09.1995.<br />Mit Inbetriebnahme der Neubaustrecke zum Louise-Schroeder-Platz wurde die Endstelle S Bornholmer Straße in Prenzlauer Berg, Björnsonstraße umbenannt. </span></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" width="834" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td colspan="2" style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><img src="http://www.berlin-straba.de/images/Neubautrassen/1995-10-14_Schroederplatz_800px.jpg" width="800" height="125" style="vertical-align: top;" /></p></td></tr>\u000a<tr>\u000a<td width="70" style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600;">Wedding, Louise-Schroeder-Platz</span><span style=" font-size:10pt;"> - Seestraße - Osloer Straße - Bornholmer Straße - Wisbyer Straße - Prenzlauer Promenade - Langhansstraße - Antonplatz - Berliner Allee - Indira-Gandhi-Straße - Weißenseer Weg - Möllendorffstraße - Bf. Frankfurter Allee - Gürtelstraße - Scharnweberstraße - Weichselstraße - Holteistraße - Wühlischstraße - Kopernikusstraße - Warschauer Straße - </span><span style=" font-size:10pt; font-weight:600;">S+U Warschauer Straße</span></p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; font-size:10pt; font-weight:600;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Auf der Linie 23 werden nur Wagen vom Typ KT4D-t mod vom Betriebshof Weißensee eingesetzt. Die Linie 24 wird komplett mit Wagen vom Typ GT6N vom Betriebshof Marzahn befahren.</span></p></td>\u000a<td width="754" style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt;"> </span></p></td></tr></table></body></html>'),0,0,'2012-07-01 13:56:49');
