INSERT INTO Comments VALUES(751,unistr('13.07.2009\u000aFreigabe Heinersdorf'),'1002','2009/07/13','["M2"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">13.07.2009</span><br />Freigabe Heinersdorf</p>\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" color:#008000;">24h-Linie</span></p>\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Heinersdorf</span><span style=" font-size:10pt; color:#ff0000;"> - Romain-Rolland-Straße -</span><span style=" font-size:10pt;"> Berliner Straße - </span><span style=" font-size:10pt; font-weight:600; color:#008000;">Am Steinberg</span><span style=" font-size:10pt; color:#008000;"> - Prenzlauer Promenade - Prenzlauer Allee - Karl-Liebknecht-Straße - Dircksenstraße - </span><span style=" font-size:10pt; font-weight:600; color:#008000;">S+U Alexanderplatz/Dircksenstraße </span></p>\u000a<p style="-qt-paragraph-type:empty; margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; font-size:10pt; color:#008000;"><br /></p></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(752,unistr('30.05.2007\u000aInbetriebnahme Strecke Prenzlauer Allee - S+U Alexanderplatz/Dircksenstraße '),'1002','2007/05/30','["M2"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">30.05.2007</span><br />Inbetriebnahme Strecke Prenzlauer Allee - S+U Alexanderplatz/Dircksenstraße </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Die Strecke Prenzlauer Allee/Mollstraße - S+U Alexanderplatz/Dircksenstraße wurde am 30.05.2007 gegen ca. 11:20 Uhr mit dem Wagen 2006 (GT6N-Z) eröffnet. Gegen ca. 12:00 Uhr erreichte der erste planmäßige Linienzug (2026 - GT6N-Z) die neue Endstelle in der Dircksenstraße. Da die Endstelle in der Dircksenstraße als Stumpfendstelle gebaut wurde, konnten ab 30.05.2007 nur noch Zweirichtungswagen auf der Linie M2 eingesetzt werden. Der 24-Stunden-Betrieb erfolgte nur noch auf dem Abschnitt Am Steinberg - S+U Alexanderplatz/Dircksenstraße </span></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" width="834" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td colspan="2" style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><img src="http://www.berlin-straba.de/images/Neubautrassen/2007-05-30_Alex2_800px.jpg" width="800" height="177" style="vertical-align: top;" /></p></td></tr>\u000a<tr>\u000a<td width="70" style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" color:#008000;">24h-Linie</span></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600;">Heinersdorf</span><span style=" font-size:10pt;"> - Romain-Rolland-Straße - Berliner Straße - </span><span style=" font-size:10pt; font-weight:600; color:#008000;">Am Steinberg</span><span style=" font-size:10pt; color:#008000;"> - Prenzlauer Promenade - Prenzlauer Allee</span><span style=" font-size:10pt;"> - </span><span style=" font-size:10pt; color:#ff0000;">Karl-Liebknecht-Straße - Dircksenstraße - </span><span style=" font-size:10pt; font-weight:600; color:#ff0000;">S+U Alexanderplatz/Dircksenstraße </span></p></td>\u000a<td width="754" style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"> </p></td></tr></table></body></html>'),0,0,'2012-07-03T15:25:55Z');
