INSERT INTO Comments VALUES(763,unistr('29.09.2000\u000aInbetriebnahme Französisch Buchholz\u000aLetzter Einsatztag von T6A2 mod / B6A2 mod im Raum Pankow '),'50','2000/09/29','["50"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">29.09.2000</span><br />Inbetriebnahme Französisch Buchholz<br />Letzter Einsatztag von T6A2 mod / B6A2 mod im Raum Pankow </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-weight:600; font-style:italic;">Am 29.09.2000 wurde die Strecke zur Endstelle Französisch Buchholz, Guyotstraße feierlich eröffnet. In den 1990-er Jahren entstanden hier neue Wohnungen. Eröffnet wurde die Strecke um ca. 14:30 Uhr nach durchfahren des Eröffnungskonvois durch die Wagen GT6N (1040), GT6N (1022) und T24 (5984). Ebenfalls am 29.09.2000 erfolgten die letzten Einsätze der Wagen vom Typ T6A2 mod und B6A2 mod auf den Linien 50, 52 und 53. Alle Wagen wurden zum Betriebshof Marzahn überführt und kamen zum Teil auf der Linie 26 und 28 zum Einsatz. </span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><img src="http://www.berlin-straba.de/images/Neubautrassen/2000-09-29_Guyotstr_800px.jpg" width="800" height="131" /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Französisch Buchholz, Guyotstraße</span><span style=" font-size:10pt; color:#ff0000;"> - Rosenthaler Weg - Mühlenstraße - Hauptstraße - Berliner Straße - Pasewalker Straße - Prenzlauer Chaussee - S-Bf. Pankow-Heinersdorf - Bleicheroder Straße - Stiftsweg - Breite Straße </span><span style=" font-size:10pt;">- Berliner Straße - Schönhauser Allee - Kastanienallee - Zionskirchplatz - Veteranenstraße - Invalidenstraße - Chausseestraße - Oranienburger Tor - Friedrichstraße - Dorotheenstraße - &upPlanckstraße - &upGeorgenstraße - &upAm Kupfergraben - </span><span style=" font-size:10pt; font-weight:600;">Mitte, Am Kupfergraben</span></p></body></html>'),0,0,'2012-07-01 13:56:49');
