INSERT INTO Comments VALUES(771,unistr('25.10.1997\u000aInbetriebnahme Strecke Louise-Schroeder-Platz - Virchow-Klinikum \u000a'),'23','1997/10/25','["23"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">25.10.1997</span><br />Inbetriebnahme Strecke Louise-Schroeder-Platz - Virchow-Klinikum </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-weight:600; font-style:italic;">Die Verlängerung zum Virchow-Klinikum wurde am 25.10.1997 eröffnet. Anfangs wurde die Strecke komplett mit GT6N auf den Linie 23 und 24 befahren. Da jedoch die Kapazitäten auf der Linie 23 nicht ausreichten, wurde ab November 1997 wieder jeder zweite Umlauf mit KT4D mod bzw. KT4D-t mod in Traktion gefahren.</span><span style=" font-size:9pt; font-weight:600; font-style:italic;"> </span></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" width="834" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td colspan="2" style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><img src="http://www.berlin-straba.de/images/Neubautrassen/1997-10-25_Virchowklinikum_800px.jpg" width="800" height="128" style="vertical-align: top;" /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Wedding, Virchow-Klinikum</span><span style=" font-size:10pt; color:#ff0000;"> - Seestraße</span><span style=" font-size:10pt;"> - Osloer Straße - Bornholmer Straße - Wisbyer Straße - Prenzlauer Promenade - Langhansstraße - Antonplatz - Berliner Allee - Indira-Gandhi-Straße - Weißenseer Weg - Möllendorffstraße - Bf. Frankfurter Allee - Gürtelstraße - Scharnweberstraße - Weichselstraße - Holteistraße - Wühlischstraße - Kopernikusstraße - Warschauer Straße - </span><span style=" font-size:10pt; font-weight:600;">S+U Warschauer Straße</span></p></td></tr></table></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(772,unistr('25.10.1997\u000aInbetriebnahme Strecke Louise-Schroeder-Platz - Virchow-Klinikum '),'24','1997/10/25','["24"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">25.10.1997</span><br />Inbetriebnahme Strecke Louise-Schroeder-Platz - Virchow-Klinikum </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-weight:600; font-style:italic;">Die Verlängerung zum Virchow-Klinikum wurde am 25.10.1997 eröffnet. Anfangs wurde die Strecke komplett mit GT6N auf den Linie 23 und 24 befahren. Da jedoch die Kapazitäten auf der Linie 23 nicht ausreichten, wurde ab November 1997 wieder jeder zweite Umlauf mit KT4D mod bzw. KT4D-t mod in Traktion gefahren. </span></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" width="834" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td colspan="2" style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><img src="http://www.berlin-straba.de/images/Neubautrassen/1997-10-25_Virchowklinikum_800px.jpg" width="800" height="128" style="vertical-align: top;" /></p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Wedding, Virchow-Klinikum</span><span style=" font-size:10pt; color:#ff0000;"> - Seestraße</span><span style=" font-size:10pt;"> - Osloer Straße - Bornholmer Straße - Wisbyer Straße - Prenzlauer Promenade - Langhansstraße - Antonplatz - Berliner Allee - Buschallee - </span><span style=" font-size:10pt; font-weight:600;">Weißensee, Hansastraße</span><span style=" font-size:10pt;"><br /></span><span style=" font-size:10pt; font-style:italic;">verkehrt nur montags bis samstags bis ca. 19:00 Uhr</span></p></td></tr></table></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(773,unistr('03.11.1997\u000aInbetriebnahme Linie 24E '),'1017','1997/11/03','["24E"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">03.11.1997</span><br />Inbetriebnahme Linie 24E </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Aufgrund der großen Nachfrage musste die Linie 24 während des Frühberufsverkehrs zwischen Virchow-Klinikum und Björnsonstraße durch die Linie 24E verstärkt werden.</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Wedding, Virchow-Klinikum</span><span style=" font-size:10pt; color:#ff0000;"> - Seestraße - Osloer Straße - Bornholmer Straße - Prenzlauer Berg, </span><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Björnsonstraße</span><span style=" font-size:10pt; color:#ff0000;"><br /></span><span style=" font-size:10pt; font-style:italic; color:#ff0000;">verkehrt nur im Frühberufsverkehr</span></p></body></html>'),0,0,'2012-07-01 13:56:49');
INSERT INTO Comments VALUES(774,unistr('20.12.1997\u000aInbetriebnbahme Strecke Friedrichstraße - Dorotheenstraße \u000a'),'1','1997/12/20','["1"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">20.12.1997</span><br />Inbetriebnbahme Strecke Friedrichstraße - Dorotheenstraße </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Ab 20.12.1997 wurde der Bahnhof Friedrichstraße direkt angefahren. Die Neubautrasse beginnt in Höhe der Einmündung Friedrichstraße/Am Weidendamm. Die Schleifenfahrt zur Endstelle Am Kupfergraben wurde auch verändert, sodass die Züge von der Friedrichstraße in die Dorotheenstraße abbiegen und zur Endstelle Am Kupfergraben fahren. Auf der Rücktour fuhren die Züge dann über Am Kupfergraben - Georgenstraße - Planckstraße - Dorotheenstraße zur Friedrichstraße.</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600;">Heinersdorf</span><span style=" font-size:10pt;"> - Romain-Rolland-Straße - Berliner Straße - Am Steinberg - Prenzlauer Promenade - Prenzlauer Allee - Torstraße - Alte Schönhauser Straße - Neue Schönhauser Straße - Rosenthaler Straße - Hackescher Markt - &upNeue Promenade - &upKleine Präsidentenstraße - Oranienburger Straße - Oranienburger Tor - </span><span style=" font-size:10pt; color:#ff0000;">Chausseesatraße - </span><span style=" font-size:10pt; font-weight:600; color:#ff0000;">U Schwartzkopffstraße</span></p></body></html>'),0,0,'2012-07-01 13:56:49');
