INSERT INTO Comments VALUES(788,unistr('18.12.1998\u000aInbetriebnahme Alexanderplatz '),'5','1998/12/18','["5"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">18.12.1998</span><br />Inbetriebnahme Alexanderplatz </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-weight:600; font-style:italic;">Nach über 30 Jahren wurde der Alexanderplatz wieder mit Straßenbahnen befahren. Da der Bereich Mollstraße/Otto-Braun-Straße weiter umgebaut wurde, konnten die Linien 2, 3 und 4 erst ab 26.04.1999 über den Alexanderplatz fahren. Dafür wurde die Linie 15 wieder über U-Bf. Rosa-Luxemburg-Platz geführt.</span><span style=" font-size:9pt; font-weight:600; font-style:italic;"> </span></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" width="834" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td colspan="2" style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><img src="http://www.berlin-straba.de/images/Neubautrassen/1998-12-18_Alex_800px.jpg" width="800" height="142" style="vertical-align: top;" /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600;">Hohenschönhausen, Zingster Straße</span><span style=" font-size:10pt;"> - Zingst