INSERT INTO Comments VALUES(860,'06.09.2004 Freigabe Grabbeallee ','52','2004/09/06','["52"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">06.09.2004</span><br />Freigabe Grabbeallee </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Nach Freigabe der Grabbeallee wurden die Zufahrtsgleise zum Betriebshof Niederschönhausen vereinfacht. Die Einfahrt erfolgt nur noch über die erste Einfahrt, die Ausfahrten können nur noch von den Toren 2 und 3 erfolgen. Bisher konnte an den Toren 1 und 2 eingefahren werden und an allen Toren ausgefahren werden.</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Niederschönhausen, Schillerstraße</span><span style=" font-size:10pt; color:#ff0000;"> - Schillerstraße - Dietzgenstraße - Ossietzkyplatz - Hermann-Hesse-Straße - Pastor-Niemöller-Platz - Grabbeallee - Schönholzer Straße</span><span style=" font-size:10pt;"> - Breite Straße - Berliner Straße - Schönhauser Allee - Kastanienallee - Weinbergsweg - Rosenthaler Platz - Rosenthaler Straße - Hackescher Markt - &upNeue Promenade - &upKleine Präsidentenstraße - Oranienburger Straße - Oranienburger Tor - Friedrichstraße - Dorotheenstraße - &upPlanckstraße - &upGeorgenstraße - &upAm Kupfergraben - </span><span style=" font-size:10pt; font-weight:600;">Mitte, Am Kupfergraben</span></p></body></html>'),0,0,'2012-07-01 13:56:49');
