INSERT INTO Comments VALUES(927,unistr('23.06.2005\u000aInbetriebnahme Linie 37 '),'37','2005/06/23','["37"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">23.06.2005</span><br />Inbetriebnahme Linie 37 </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Durch Inbetriebnahme der Linie 37 verkehrten die Verstärkerfahrten der Linie M17 (Gehrenseestraße - S Schöneweide) nur noch im Frühberufsverkehr, sowie am Wochenende.</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Betriebshof Lichtenberg</span><span style=" font-size:10pt; color:#ff0000;"> - Siegfriedstraße - Herzbergstraße - Herzberggelände - Rhinstraße - Am Tierpark - Treskowallee - Edisonstraße - Brückenstraße - Michael-Brückner-Straße - </span><span style=" font-size:10pt; font-weight:600; color:#ff0000;">S Schöneweide</span><span style=" font-size:10pt; color:#ff0000;"><br /></span><span style=" font-size:10pt; font-style:italic; color:#ff0000;">verkehrt nur montags bis freitags von 08:00 Uhr bis 19:00 Uhr</span></p></body></html>'),0,0,'2012-07-02 06:29:48');
