INSERT INTO Comments VALUES(959,unistr('28.05.2006\u000aInbetriebnahme Strecke Eberswalder Straße - S Nordbahnhof\u000aEinführung 24h-Metro Netz '),'1001','2006/05/28','["M1"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">28.05.2006</span><br />Inbetriebnahme Strecke Eberswalder Straße - S Nordbahnhof<br />Einführung 24h-Metro Netz </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Eröffnet wurde die Strecke Eberswalder Straße - S Nordbahnhof für die Linie M10 gegen ca. 11:30 Uhr durch die GT6N-Z Wagen 2039 und 2042. Gegen ca. 11:45 Uhr folgten die historischen Wagen 3802 (TM34) und 5984 (T24). Der erste Fahrgastzug war der GT6N-Z 2002 gegen ca. 12:00 Uhr. </span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Ebenfalls zum 28.05.2006 wurde das neue 24-Stunden Metronetz eingeführt. Alle Metrolinien verkehrten 24-Stunden am Tag. In der nachfolgenden Übersicht verkehren nur die </span><span style=" font-size:9pt; font-style:italic; color:#008000;">GRÜN </span><span style=" font-size:9pt; font-style:italic;">bzw. </span><span style=" font-size:9pt; font-style:italic; color:#ff0000;">ROT</span><span style=" font-size:9pt; font-style:italic;"> dargestellten Streckenführungen im 24-Stunden System. Alle </span><span style=" font-size:9pt; font-style:italic; color:#a0a0a4;">GRAU</span><span style=" font-size:9pt; font-style:italic;"> dargestellten Streckenführungen verkehrten nur von ca. 04:30 Uhr bis ca. 00:00 Uhr. </span></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" width="834" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td colspan="2" style=" vertical-align:top;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><img src="http://www.berlin-straba.de/images/Neubautrassen/2006-05-28_Bernauerstr_800px.jpg" width="800" height="138" style="vertical-align: top;" /></p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#008000;">Niederschönhausen, Schillerstraße </span><span style=" font-size:10pt; color:#008000;">- Schillerstraße - Dietzgenstraße - Ossietzkyplatz - Hermann-Hesse-Straße - Pastor-Niemöller-Platz - Grabbeallee - Schönholzer Straße - Breite Straße - Berliner Straße - Schönhauser Allee - Kastanienallee - Weinbergsweg - Rosenthaler Platz - Rosenthaler Straße - Hackescher Markt - &upNeue Promenade - &upKleine Präsidentenstraße - Oranienburger Straße - Oranienburger Tor - Friedrichstraße - Dorotheenstraße - &upPlanckstraße - &upGeorgenstraße - &upAm Kupfergraben -</span><span style=" font-size:10pt; font-weight:600; color:#008000;"> Mitte, Am Kupfergraben</span></p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; font-size:10pt; font-weight:600; color:#008000;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#a0a0a4;">Rosenthal Nord</span><span style=" font-size:10pt; color:#a0a0a4;"> - Quickborner Straße - Wilhelmsruher Damm - Friedrich-Engels-Straße -Pastor-Niemöller-Platz - Grabbeallee - Schönholzer Straße - Breite Straße - Berliner Straße - Schönhauser Allee - Kastanienallee - Weinbergsweg - Rosenthaler Platz - Rosenthaler Straße - Hackescher Markt - &upNeue Promenade - &upKleine Präsidentenstraße - Oranienburger Straße - Oranienburger Tor - Friedrichstraße - Dorotheenstraße - &upPlanckstraße - &upGeorgenstraße - &upAm Kupfergraben - </span><span style=" font-size:10pt; font-weight:600; color:#a0a0a4;">Mitte, Am Kupfergraben</span></p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; font-size:10pt; font-weight:600; color:#a0a0a4;"><br /></p></td></tr></table></body></html>'),0,0,'2012-07-03T12:03:16Z');
