INSERT INTO Comments VALUES(983,unistr('19.01.2009\u000aEingleisiger Betrieb in der Bornholmer Straße '),'1006','2009/01/19','["M13"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">19.01.2009</span><br />Eingleisiger Betrieb in der Bornholmer Straße </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Wegen Sanierungsarbeiten und Tiefbauarbeiten in der Bornholmer Straße wurden zwei eingleisige Strecken (Björnonstraße - Schönfließer Straße und Schönfließer Straße - Schönhauser Allee) eingerichtet. Da auch im Kreuzungsbereich Bornholmer Straße/Björnsonstraße Tiefbauarbeiten am Gleis in Richtung Schönhauser Allee stattfanden, mussten die Züge von der Osloer Straße kommend über die Gleisschleife Björnsonstraße fahren.</span></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#a0a0a4;">Französisch Buchholz, Guyotstraße</span><span style=" font-size:10pt; color:#a0a0a4;"> - Rosenthaler Weg - Mühlenstraße - Hauptstraße - Berliner Straße - Pasewalker Straße - Prenzlauer Chaussee - S Pankow-Heinersdorf - Bleicheroder Straße - Stiftsweg - Breite Straße - Berliner Straße - Bornholmer Straße (- Prenzlauer Berg, Björnsonstraße) - </span><span style=" font-size:10pt; color:#ff0000;">&upGleisschleife Björnonstraße</span><span style=" font-size:10pt; color:#a0a0a4;"> - Bornholmer Straße - Osloer Straße - Seestraße - </span><span style=" font-size:10pt; font-weight:600; color:#a0a0a4;">Wedding, Virchow-Klinikum</span><span style=" font-size:10pt;"><br /></span><span style=" font-size:10pt; font-style:italic;">Guyotstraße - Virchow.Klinikum nur montags bis freitags bis ca. 19:00 Uhr, sonnabends nur 09:00 Uhr bis 18:00 Uhr</span></p></body></html>'),0,0,'2012-07-03T19:38:01Z');
