INSERT INTO Comments VALUES(1036,unistr('10.07.1953\u000aLinienänderung Linie 74 (BVG-Ost)'),'74','1953/07/10','["74"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">10.07.1953</span><br />Linienänderung Linie 74 (BVG-Ost)</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600;">Weißensee, Rennbahnstraße</span><span style=" font-size:10pt;"> - Rennbahnstraße - Klement-Gottwald-Allee - Greifswalder Straße - Königstor - Neue Königstraße - &downJostystraße - &downPrenzlauer Straße - Memhardstraße - Alexanderplatz - Alexanderstraße - Schicklerstraße - Stralauer Straße - Molkenmarkt - Mühlendamm - Gertraudenstraße - Spittelmarkt - Leipziger Straße - </span><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Leipziger Platz</span></p></body></html>'),0,0,'2012-07-05 20:41:00');
INSERT INTO Comments VALUES(1037,unistr('15.01.1953 / 16.01.1953\u000aStraßenbahnspaltung zwischen Ostberlin und Westberlin\u000aStilllegung Prinzenallee, teilw. Gitschiner Straße - nördl. Wollankstraße, Hauptstraße (Wilhelmsruh) \u000a'),'74','1953/01/15','["74"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">15.01.1953 / 16.01.1953<br />Straßenbahnspaltung zwischen Ostberlin und Westberlin<br />Stilllegung Prinzenallee, teilw. Gitschiner Straße - nördl. Wollankstraße, Hauptstraße (Wilhelmsruh) </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Am Nachmittag, des 15.01.1953 erfolgte die so genannte &quot;Straßenbahn-Spaltung&quot; in Berlin. Die BVG-Ost schickte wieder vermehrt, in den Vormittagsstunden, Straßenbahnfahrerinnen auf den Linien 74 und 95 in Richtung Westberlin, obwohl der Einsatz von Fahrerinnen auf Westberliner Gebiet nach damaligen Vorschriften nicht statthaft war. Die Züge wurden wieder nach Ostberlin zurück geschickt und die Züge der BVG-West wurden nicht nach Ostberlin geschickt, als Ersatz für das Fehlen der Züge der BVG-Ost.</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600;">Weißensee, Rennbahnstraße</span><span style=" font-size:10pt;"> - Rennbahnstraße - Klement-Gottwald-Allee - Greifswalder Straße - Königstor - Neue Königstraße - &downJostystraße - &downPrenzlauer Straße - Memhardstraße - Alexanderplatz - Alexanderstraße - Schicklerstraße - Stralauer Straße - Molkenmarkt - Mühlendamm - Gertraudenstraße - Spittelmarkt - Leipziger Straße - </span><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Leipziger Platz</span></p></body></html>'),0,0,'2012-07-05 20:46:46');
INSERT INTO Comments VALUES(1038,unistr('01.06.1949 \u000aWiederinbetriebnahme Linien 25\u000aEinführung von Fahrscheinstemmpel (Wegfall von dreistelligen Liniennummern)\u000aFreigabe Potsdamer Platz '),'74','1949/06/01','["74"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">01.06.1949 <br />Wiederinbetriebnahme Linien 25<br />Einführung von Fahrscheinstemmpel (Wegfall von dreistelligen Liniennummern)<br />Freigabe Potsdamer Platz </p>\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Mit der Einführung von Fahrscheinstempel wurden alle dreistelligen Liniennummern in zweistellige umbenannt. Linie 129 in 29, Linie 141 in 36, Linie 47 in 46, Linie 147 in 47, Linie 174 in 73 und Linie 199 in 45</span></p>\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600;">Weißensee, Rennbahnstraße</span><span style=" font-size:10pt;"> - Rennbahnstraße - Berliner Allee - Greifswalder Straße - Königstor - Neue Königstraße - &downJostystraße - &downPrenzlauer Straße - Memhardstraße - Alexanderplatz - Königstraße - Spandauer Straße - Molkenmarkt - Mühlendamm - Gertraudenstraße - Spittelmarkt - Leipziger Straße - Leipziger Platz - Potsdamer Platz - Potsdamer Straße - Kaiser-Wilhelm-Platz - Hauptstraße - Innsbrucker Platz - Rheinstraße - Schloßstraße - Hindenburgdamm - Händelplatz - Hindenburgdamm - Wiesenbaude - Finckensteinallee - </span><span style=" font-size:10pt; font-weight:600;">Lichterfelde, Finckensteinallee</span><span style=" font-size:10pt;"><br /></span><span style=" font-size:10pt; font-style:italic; color:#008000;">Schaffnerwechsel Potsdamer Straße/Linkstraße</span></p></body></html>'),0,0,'2012-07-05 20:54:43');
INSERT INTO Comments VALUES(1039,unistr('09.07.1948\u000aBeginn Berlin-Blockade (Stromeinsparung)'),'74','1948/07/09','["74"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">09.07.1948 </span><br />Beginn Berlin-Blockade (Stromeinsparung)</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td style=" vertical-align:top;">\u000a<p align="justify" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600;">Weißensee, Rennbahnstraße</span><span style=" font-size:10pt;"> - Rennbahnstraße - Berliner Allee - Greifswalder Straße - Königstor - Neue Königstraße - &downJostystraße - &downPrenzlauer Straße - Memhardstraße - Alexanderplatz - Königstraße - Spandauer Straße - Molkenmarkt - Mühlendamm - Gertraudenstraße - Spittelmarkt - Leipziger Straße</span><span style=" font-size:10pt; color:#ff0000;"> (- Charlottenstraße - &upFranzösische Straße - &upKanonierstraße - </span><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Taubenstraße</span><span style=" font-size:10pt; color:#ff0000;">) </span><span style=" font-size:10pt;">- Leipziger Platz - Potsdamer Platz - Potsdamer Straße - Kaiser-Wilhelm-Platz - Hauptstraße - Innsbrucker Platz - Rheinstraße - Schloßstraße - Hindenburgdamm - Händelplatz - Hindenburgdamm - Wiesenbaude - Finckensteinallee - </span><span style=" font-size:10pt; font-weight:600;">Lichterfelde, Finckensteinallee</span><span style=" font-size:10pt;"><br /></span><span style=" font-size:10pt; font-style:italic; color:#ff0000;">Ab 18:00 Uhr nur Rennbahnstraße - Taubenstraße</span></p></td>\u000a<td></td></tr>\u000a<tr>\u000a<td style=" vertical-align:top;"></td>\u000a<td style=" vertical-align:top;"></td></tr></table></body></html>'),0,0,'2012-07-05T21:10:08Z');
INSERT INTO Comments VALUES(1040,unistr('24.03.1949 \u000aEinführung Schaffnerwechsel an den Sektorengrenzen \u000a'),'74','1949/03/24','["74"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">24.03.1949 </span><br />Einführung Schaffnerwechsel an den Sektorengrenzen </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Im März 1949 wurde entschieden, dass die Westmark (DM) als allein gültiges Zahlungsmittel in West-Berlin einzuführen ist. Aus diesem Grunde mußte an der Sektorengrenze zwischen der Sowjetzone und den anderen drei alliierten Zonen ein Schaffnerwechsel durchgeführt werden.</span></p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600;">Weißensee, Rennbahnstraße</span><span style=" font-size:10pt;"> - Rennbahnstraße - Berliner Allee - Greifswalder Straße - Königstor - Neue Königstraße - &downJostystraße - &downPrenzlauer Straße - Memhardstraße - Alexanderplatz - Königstraße - Spandauer Straße - Molkenmarkt - Mühlendamm - Gertraudenstraße - Spittelmarkt - Leipziger Straße (- Charlottenstraße - &upFranzösische Straße - &upKanonierstraße - </span><span style=" font-size:10pt; font-weight:600;">Taubenstraße</span><span style=" font-size:10pt;">) - Leipziger Platz - Potsdamer Platz - </span><span style=" font-size:10pt; color:#008000;">Potsdamer Straße/Linkstraße</span><span style=" font-size:10pt;"> - Potsdamer Straße - Kaiser-Wilhelm-Platz - Hauptstraße - Innsbrucker Platz - Rheinstraße - Schloßstraße - Hindenburgdamm - Händelplatz - Hindenburgdamm - Wiesenbaude - Finckensteinallee - </span><span style=" font-size:10pt; font-weight:600;">Lichterfelde, Finckensteinallee</span><span style=" font-size:10pt;"><br /></span><span style=" font-size:10pt; font-style:italic;">Ab 18:00 Uhr nur Rennbahnstraße - Taubenstraße</span><span style=" font-size:10pt; font-style:italic;"><br /></span><span style=" font-size:10pt; font-style:italic; color:#008000;">Schaffnerwechsel Potsdamer Straße/Linkstraße</span></p></body></html>'),0,0,'2012-07-05 21:19:41');
INSERT INTO Comments VALUES(1041,unistr('25.03.1949 \u000aSperrung Leipziger Straße '),'1096','1949/03/25','["74E.2"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">25.03.1949 </span><br />Sperrung Leipziger Straße </p>\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Wegen Abrißarbeiten an der Wertheim-Ruine und anderer Gebäude musste die Leipziger Straße für den Straßenbahnverkehr gesperrt werden.</span></p>\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; color:#ff0000;">Teil II</span></p>\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; color:#ff0000;">Kurfürstenstraße </span><span style=" font-size:10pt;">- Potsdamer Straße - Kaiser-Wilhelm-Platz - Hauptstraße - Innsbrucker Platz - Rheinstraße - Schloßstraße - Hindenburgdamm - </span><span style=" font-size:10pt; font-weight:600;">Lichterfelde, Händelplatz</span><span style=" font-size:10pt;"><br /></span><span style=" font-size:10pt; font-style:italic;">Betriebsschluß 18:00 Uhr</span></p></body></html>'),0,0,'2012-07-05 21:39:58');
