INSERT INTO Comments VALUES(1043,unistr('01.06.1949 \u000aWiederinbetriebnahme Linien 25\u000aEinführung von Fahrscheinstemmpel (Wegfall von dreistelligen Liniennummern)\u000aFreigabe Potsdamer Platz '),'73','1949/06/01','["73"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">01.06.1949 </span><br />Wiederinbetriebnahme Linien 25<br />Einführung von Fahrscheinstemmpel (Wegfall von dreistelligen Liniennummern)<br />Freigabe Potsdamer Platz </p>\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Mit der Einführung von Fahrscheinstempel wurden alle dreistelligen Liniennummern in zweistellige umbenannt. Linie 129 in 29, Linie 141 in 36, Linie 47 in 46, Linie 147 in 47, Linie 174 in 73 und Linie 199 in 45</span></p>\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Weißensee, Rennbahnstraße </span><span style=" font-size:10pt; color:#ff0000;">- Rennbahnstraße - Berliner Allee - Antonplatz - Greifswalder Straße - Königstor - Neue Königstraße - &downJostystraße - &downPrenzlauer Straße - &downMemhardstraße - Alexanderplatz - Königstraße - Spandauer Straße - Molkenmarkt - Mühlendamm - Gertraudenstraße - Spittelmarkt - Leipziger Straße - Leipziger Platz - Potsdamer Platz - Potsdamer Straße - Hauptstraße - Innsbrucker-Platz - Rheinstraße - Schloßstraße - Hindenburgdamm - Wiesenbaude - Giesensdorfer Straße - Wilhelmstraße - Jungfernstieg - </span><span style=" font-size:10pt; font-weight:600; color:#ff0000;">S-Bf. Lichterfelde-Ost</span><span style=" font-size:10pt;"><br /></span><span style=" font-size:10pt; font-style:italic; color:#008000;">Schaffnerwechsel Potsdamer Straße/Linkstraße</span></p></body></html>'),0,0,'2012-07-05 21:54:36');
INSERT INTO Comments VALUES(1045,unistr('01.09.1949 \u000aVerwaltungstrennung in BVG-Ost und BVG-West \u000a'),'','1949/09/01','[]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">01.09.1949 </span><br />Verwaltungstrennung in BVG-Ost und BVG-West </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Am 01. August 1949 erfolgte die Verwaltungstrennung auf Grund politischer Spaltung Berlins. Getrennt wurde in eine Verwaltung BVG-Ost und in eine Verwaltung BVG-West. Zu diesem Zeitpunkt gab es 16 Linien die von der BVG-Ost, 28 Linien die von der BVG-West und 6 Linien die von beiden Verwaltungen betrieben wurden (E-Linien nicht mitberechnet).</span><span style=" font-size:9pt; font-style:italic;"> </span></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" width="834" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-weight:600;">Linien die von der BVG-Ost betrieben wurden:</span><br />1, 4, 13, 45, 46, 49, 64, 65, 69, 71, 72, 82, 83, 84, 86, 87</p></td></tr>\u000a<tr>\u000a<td>\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-weight:600;"><br />Linien die von der BVG-West betrieben wurden:</span><br />2, 6, 15, 21, 25, 27, 28, 29, 35, 36, 40, 41, 47, 51, 54, 55, 57, 60, 62, 66, 68, 75, 76, 77,88, 93, 96, 99 </p></td></tr>\u000a<tr>\u000a<td>\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-weight:600;"><br />Linien die von beiden Verwaltungen gleichermaßen betrieben wurden:</span><br />3, 23, 24, 73, 74, 95 </p></td></tr></table></body></html>'),0,0,'2012-07-05 22:00:02');
INSERT INTO Comments VALUES(1046,unistr('27.04.1955\u000aSperrung Leipziger Straße '),'74','1955/04/27','["74"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">27.04.1955<br />Sperrung Leipziger Straße </p>\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Wegen abschließender Abrißarbeiten an der Wertheim-Ruine musste die Leipziger Straße für den Straßenbahnverkehr gesperrt werden.</span></p>\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600;">Weißensee, Rennbahnstraße</span><span style=" font-size:10pt;"> - Rennbahnstraße - Klement-Gottwald-Allee - Greifswalder Straße - Königstor - Neue Königstraße - &downJostystraße - &downPrenzlauer Straße - Memhardstraße - Alexanderplatz - Alexanderstraße - Schicklerstraße - Stralauer Straße - Molkenmarkt - Mühlendamm - Gertraudenstraße - Spittelmarkt - Leipziger Straße - </span><span style=" font-size:10pt; color:#ff0000;">Charlottenstraße - </span><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Charlottenstraße/Taubenstraße</span></p></body></html>'),0,0,'2012-07-05 22:16:48');
