INSERT INTO Comments VALUES(1065,unistr('15.01.1953 / 16.01.1953\u000aStraßenbahnspaltung zwischen Ostberlin und Westberlin\u000aStilllegung Prinzenallee, teilw. Gitschiner Straße - nördl. Wollankstraße, Hauptstraße (Wilhelmsruh) '),'76','1953/01/16','["76"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">15.01.1953 / 16.01.1953</span><br />Straßenbahnspaltung zwischen Ostberlin und Westberlin<br />Stilllegung Prinzenallee, teilw. Gitschiner Straße - nördl. Wollankstraße, Hauptstraße (Wilhelmsruh) </p>\u000a<p align="justify" style=" margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Am Nachmittag, des 15.01.1953 erfolgte die so genannte &quot;Straßenbahn-Spaltung&quot; in Berlin. Die BVG-Ost schickte wieder vermehrt, in den Vormittagsstunden, Straßenbahnfahrerinnen auf den Linien 74 und 95 in Richtung Westberlin, obwohl der Einsatz von Fahrerinnen auf Westberliner Gebiet nach damaligen Vorschriften nicht statthaft war. Die Züge wurden wieder nach Ostberlin zurück geschickt und die Züge der BVG-West wurden nicht nach Ostberlin geschickt, als Ersatz für das Fehlen der Züge der BVG-Ost.</span></p>\u000a<p align="justify" style="-qt-paragraph-type:empty; margin-top:12px; margin-bottom:12px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; font-size:9pt; font-style:italic;"><br /></p>\u000a<table border="0" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px;" cellspacing="2" cellpadding="0">\u000a<tr>\u000a<td style=" vertical-align:top;">\u000a<p align="justify" style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Kurfürstenstraße/Potsdamer Straße</span><span style=" font-size:10pt; color:#ff0000;"> - Kurfürstenstraße - Potsdamer Straße - Bülowstraße - Nollendorfplatz</span><span style=" font-size:10pt;"> - Kleiststraße - Wittenbergplatz - Tauentzienstraße - Gedäctniskirche - Hardenbergstraße - Bf. Zoo - Joachimstaler Straße - Kurfürstendamm - S-Bf. Halensee - &downHubertusallee - &downHubertusbader Straße - &downTeplitzer Straße - &downRoseneck - &downHagenstraße - &downHagenplatz - &upKönigsallee - </span><span style=" font-size:10pt; font-weight:600;">Hundekehle</span><span style=" font-size:10pt;"><br /></span><span style=" font-size:10pt; color:#ff0000;">sonntags nur Bf. Zoo - Hundekehle</span></p></td>\u000a<td></td></tr>\u000a<tr>\u000a<td style=" vertical-align:top;"></td>\u000a<td style=" vertical-align:top;"></td></tr></table></body></html>'),0,0,'2012-07-08 22:36:00');
INSERT INTO Comments VALUES(1066,unistr('26.01.1953\u000aInbetriebnahme Kehranlagen S-Bf. Wollankstraße, S-Bf. Wilhelmsruh und Schöneberger Ufer'),'76','1953/01/26','["76"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">26.01.1953</span><br />Inbetriebnahme Kehranlagen S-Bf. Wollankstraße, S-Bf. Wilhelmsruh und Schöneberger Ufer</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Schöneberger Ufer</span><span style=" font-size:10pt; color:#ff0000;"> - Flottwellstraße - Lützowstraße - Lützowplatz - Schillstraße - Nettelbeckplatz </span><span style=" font-size:10pt;">- Kleiststraße - Wittenbergplatz - Tauentzienstraße - Gedäctniskirche - Hardenbergstraße - Bf. Zoo - Joachimstaler Straße - Kurfürstendamm - S-Bf. Halensee - &downHubertusallee - &downHubertusbader Straße - &downTeplitzer Straße - &downRoseneck - &downHagenstraße - &downHagenplatz - &upKönigsallee - </span><span style=" font-size:10pt; font-weight:600;">Hundekehle</span><span style=" font-size:10pt;"><br /></span><span style=" font-size:10pt;">sonntags nur Bf. Zoo - Hundekehle</span></p></body></html>'),0,0,'2012-07-08 22:52:18');
