INSERT INTO Comments VALUES(1068,unistr('02.05.1959\u000aInbetriebnahme Linien 53 und 76 (BVG-West)'),'76','1959/05/02','["76"]',unistr('<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\u000a<html><head><meta name="qrichtext" content="1" /><style type="text/css">\u000ap, li { white-space: pre-wrap; }\u000a</style></head><body style=" font-family:''Ubuntu''; font-size:11pt; font-weight:400; font-style:normal;">\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:12pt; font-weight:600;">02.05.1959</span><br />Inbetriebnahme Linien 53 und 76 (BVG-West)</p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Johannesstift</span><span style=" font-size:10pt; color:#ff0000;"> - Schönwalder Allee - Schönwalder Straße - Neuendorfer Straße - &upAm Juliusturm - &upBreite Straße - &upSpandau, Markt - Carl-Schurz-Straße - Münsingerplatz - Klosterstraße - Pichelsdorfer Straße - Heerstraße - Reichskanzlerplatz - Masurenallee - S-Bf. Witzleben - Neue Kantstraße - Kantstraße - </span><span style=" font-size:10pt; font-weight:600; color:#ff0000;">Bf. Zoo, Kantstraße</span></p>\u000a<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\u000a<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><span style=" font-size:9pt; font-style:italic;">Die Linie 76 existierte bereits bis zur ersten Stilllegung am 01.07.1954 und wurde nun noch einmal mit einer anderen Linienführung eingeführt, da noch au